/* DAWAH X — ahmad, অধ্যায় 25 · খণ্ড 25 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][25]=[[4801,4801,"","আমরা একটি বিড়ম্বনা নিয়ে কথা বলেছি যে আমরা কিছু জিনিস নিয়ে এসেছি, কিছু একটা বের হওয়ার অর্থ হলো বের হওয়া। প্রার্থনা করা এমন একটা ছেলে যে কিনা একজন অতিমানবের দ্বারা বড় হয়েছে, আর সে সব কিছুর জন্য খুব দ্রুতই অপেক্ষা করবে। বোকা.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَيَّانَ يَعْنِي الْبَارِقِيَّ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنَّ إِمَامَنَا يُطِيلُ الصَّلَاةَ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَكْعَتَانِ مِنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَفُّ ‏ ‏أَوْ مِثْلُ رَكْعَةٍ مِنْ صَلَاةِ هَذَا ‏","","",""],[4802,4802,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা একটা দাঙ্গার সৃষ্টি করেছি... ...যার মানে হচ্ছে একটা কুত্তীরের বাচ্চার জন্য অপমান। ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি বললেন তোমাকে থামাতে না। তুমি কিভাবে সেরা ছিলে তা খুঁজে বের করো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ يَعْنِي السَّخْتِيَانِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا نِسَاءَكُمْ الْمَسَاجِدَ ‏","","",""],[4803,4803,"","আমি যা করেছি তার ব্যাপারে কথা বলার জন্য আমরা একটি উপায় খুঁজে বের করার চেষ্টা করেছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আশ্বস্ত করেছেন যে তিনি দু'জন তৈরি করবেন না, আর তার সাথে থাকতে হবে না। মানুষ শিকার করে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَيُّوبَ بْنَ مُوسَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَتَنَاجَ ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا وَلَا يُقِيمُ الرَّجُلُ أَخَاهُ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ ‏","","",""],[4804,4804,"","আমরা প্রবল আবেগে বাপ্তাইজিত হয়েছি, যা আমরা সন্তানের আনন্দের সাথে নিয়ে এসেছি। আমি যাওয়ার পথ পেয়েছি, তিনি প্রার্থনা করেছিলেন তিনি তাকে বলতে বলেছেন আমরা কি করেছি এবং তিনি বলেছিলেন আমরা করেছি আমরা কি করা হবে. ঠিক আছে, আমরা একটি জীবনের সন্তানের স্বপ্ন সম্পর্কে কথা বলেছি. আমি একটি শিশুর জন্য একটি প্রাণপ্রার্থী সন্তানের কল্পনা সম্পর্কে কথা বলেছি মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏صَحِبْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَجَعَلَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ نَاحِيَةَ ‏ ‏مَكَّةَ ‏ ‏فَقُلْتُ ‏ ‏لِسَالِمٍ ‏ ‏لَوْ كَانَ وَجْهُهُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَيْفَ كَانَ ‏ ‏يُصَلِّي قَالَ سَلْهُ فَسَأَلْتُهُ فَقَالَ ‏ ‏نَعَمْ وَهَاهُنَا وَهَاهُنَا وَقَالَ لِأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَهُ ‏ ‏حَدَّثَنَاه ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏مَوْلَى آلِ ‏ ‏عُمَرَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[4805,4805,"","আমরা একটি দাঙ্গার কথা বলেছি যে তার দুই ছেলে তার নাম শুনেছে, সে আমাকে এক রাত ধরে ফোন করেছে, আমি যেন হতে পারি রাতভর বাকিটা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بِاللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَيُوتِرُ ‏ ‏بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[4806,4806,"","আমরা একটা দাঙ্গার কথা বলেছি যেটা আমাকে এমন একটা রীতিতে পরিণত করেছে যেটা আমার কাছে এসেছে যেটা শুনে সে এমন একজন লোককে দেখেছে যে তার ভ্রমণ করার জন্য ভাড়া করেছে. আল্লাহ্‌র প্রার্থনা শুনেছেন, তিনি আমার অনুমতি নিয়ে এসেছিলেন, যে তার অতিথিকে নিয়ে আর কখনো আসতে দিবেন না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏مُسْلِمَ بْنَ يَنَّاقٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ رَأَى رَجُلًا يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَقَالَ مِمَّنْ أَنْتَ فَانْتَسَبَ لَهُ فَإِذَا رَجُلٌ مِنْ ‏ ‏بَنِى لَيْثٍ ‏ ‏فَعَرَفَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُذُنَيَّ هَاتَيْنِ يَقُولُ ‏ ‏مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏لَا يُرِيدُ بِذَلِكَ إِلَّا ‏ ‏الْمَخِيلَةَ ‏ ‏فَإِنَّ اللَّهَ تَعَالَى لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4807,4807,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যেটা আমাদের জন্য একটা শিয়ালের দাঙ্গা ডেকে এনেছে যেটা আমি একটি ছেলে হতে শুনেছি, ঈশ্বর প্রার্থনা করেছিলেন বা বললেন যে তাকে মার খেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏سَمِعْتُ ‏ ‏ذَكْوَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَاذَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ضَرَبَ غُلَامًا لَهُ حَدًّا لَمْ يَأْتِهِ ‏ ‏أَوْ لَطَمَهُ ‏ ‏فَإِنَّ كَفَّارَتَهُ أَنْ يُعْتِقَهُ ‏","","",""],[4808,4808,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...যে কিনা বল যে সে কি বলবে যে... সে ঈশ্বরের কাছে প্রার্থনা করে... ...আর সে আমাকে কিছু বলেনি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏تَوْبَةَ الْعَنْبَرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُوَرِّقًا الْعِجْلِيَّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَوْ هُوَ سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ هَلْ تُصَلِّي الضُّحَى قَالَ لَا قَالَ ‏ ‏عُمَرُ ‏ ‏قَالَ لَا فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ لَا قَالَ فَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏أَخَالُ ‏","","",""],[4809,4809,"","আমরা কামনার প্রতি আসক্তি তৈরি করেছি... ...যে আমরা একটি রীতি তৈরি করেছি... ...যে দাঙ্গা আমার আত্মার ইচ্ছার একটি রীতি তৈরি করেছে. তিনি এমন এক তীর্থযাত্রীর কথা বলেছিলেন, যিনি তার ছেলে ও গেইলের ছেলে সম্বন্ধে বলেছিলেন । তার কাছের।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ الْحَنَفِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْبَيْتِ ‏ ‏وَسَتَأْتُونَ مَنْ يَنْهَاكُمْ عَنْهُ فَتَسْمَعُونَ مِنْهُ ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فَتَسْمَعُونَ مِنْ قَوْلِهِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏جَالِسٌ قَرِيبًا مِنْهُ ‏","","",""],[4810,4810,"","আমরা আবেগ নিয়ে প্রার্থনা করছি আমরা এক যুবককে খুঁজে পেয়েছি যে কিনা কিনা ঈশ্বরের দ্বারা কৃত একটি ছেলের কথা শুনেছে। সে তার হাত তুলে নেবে, যদি সে বড় হয় এবং আমি শেষ হয়ে যাবো। তার কাছে আছে, ঈশ্বরের কাছে আর সে এটা করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّهُ رَأَى ‏ ‏أَبَاهُ ‏ ‏يَرْفَعُ يَدَيْهِ إِذَا كَبَّرَ وَإِذَا أَرَادَ أَنْ يَرْكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ فَسَأَلْتُهُ عَنْ ذَلِكَ فَزَعَمَ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُهُ ‏","","",""],[4811,4811,"","আমরা ঈশ্বরের সাথে কথা বলেছি, আমি বাবার হাতে এরকম একটা ঘটনা পেয়েছি... ...আর সে একটা ভুল করার চেষ্টা করছে। সে আমাদের বলে কিভাবে একটা ছেলেকে নিয়ে যায়। সার্ভিস, তাকে তার কাপড় থেকে টেনে আনা হয়েছে, হতাশ হয়ে সে ঈশ্বরের মৃত্যু দেখেনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذِهِ الْأَحَادِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ وَهُوَ إِلَى حَدِيثِ ‏ ‏إِسْحَاقَ بْنِ يُوسُفَ الْأَزْرَقِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَرَّ ثَوْبًا مِنْ ثِيَابِهِ ‏ ‏مَخِيلَةً ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4812,4812,"","আমরা ঈশ্বরকে বলেছিলাম যে, বাবা যখন ক্লান্ত ছিলেন, তখন আমি আমার বাবাকে লিখতে পারি । তুমি বলো,","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ تُصِيبُنِي مِنْ اللَّيْلِ الْجَنَابَةُ فَقَالَ ‏ ‏اغْسِلْ ذَكَرَكَ ثُمَّ تَوَضَّأْ ثُمَّ ارْقُدْ ‏","","",""],[4813,4813,"","আমরা ঈশ্বরের কাছে প্রার্থনা করার সময় বাবাকে চিঠি লেখার সময় আমার বাবাকে চিঠি লিখতে বলেছিলাম । তার আত্মা, মূল্যবোধ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَرَّ ثَوْبَهُ ‏ ‏مَخِيلَةً ‏ ‏فَإِنَّ اللَّهَ تَعَالَى لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4814,4814,"","আমি আমার বাবার কথা বলেছিলাম যখন আমি এ বিষয়ে কথা বলেছি। আমি একটি ছেলে যে ঈশ্বরকে প্রার্থনা করতে শুনেছি, সে বলল আমি ঈশ্বরের কাছে প্রার্থনা করেছি যেন আমি তার কাছে প্রার্থনা করি এবং তাকে তার কাছে আমার ইচ্ছা হয় যে সে আসবে। সে-ই হবে যে , যে ব ্ যক ্ তি হবে , যে ব ্ যক ্ তি তার জন ্ যে উত ্ তম হবে । তাই, যিনি তাকে জিজ্ঞেস করবেন, সেই ব্যক্তি হবেন যিনি তাকে জিজ্ঞেস করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ الضَّبِّ قَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[4815,4815,"","আমি আমার বাবাকে চিঠি লিখতে গিয়ে ঈশ্বর সম্বন্ধে কথা বলেছিলাম, যখন আমরা তাকে আরও বেশি কিছু বলেছিলাম । আমাদের মন থেকে জানা যায় যে ছেলে পাশ হয়ে গেছে আর আমি তাকে বলেছি যে সে একজন রক্ষক হিসেবে কাজ করার সময় হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَقَّتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَنُبِّئْتُ أَنَّهُ ‏ ‏وَقَّتَ ‏ ‏لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏","","",""],[4816,4816,"","তিনি বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করছিলেন যেন তিনি তার কাছে সাহায্য চান অথবা তিনি তা ফিরিয়ে দেন । দিনের অন্ধকারে থাকতে হবে অথবা দিনের মাঝখানে থাকতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرِ أَوْ النَّخْلِ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[4817,4817,"","আমরা ঈশ্বরের সাথে কথা বলেছি, আমার বাবাকে লিখতে গিয়ে আমরা তাকে বলেছিলাম যে আমরা কাপুরুষের মত ভীত। সে এটা সিংহাসনের কাছে পৌঁছে দিতে চাইলো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ بَيْعِ النَّخْلِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ النَّخْلِ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[4818,4818,"","সেই সময়ে তিনি দুর্ঘটনার সময় ফোন করেছিলেন এবং সেটা যাচাই করে দেখেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ وَجَّهَتْ وَزَعَمَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[4819,4819,"","আমরা আমার বাবাকে লেখার সময় ঈশ্বরের কথাগুলো নিয়ে কথা বলেছি, যখন আমরা বলেছিলাম আমরা ডাইনির চেয়ে একটি রীতির শিকার হব। পাইলটের ছেলে আমাদের ঘিরে ফেলছে এবং মানুষ মারা যাচ্ছে। নিশ্চিত হয়ে বলতে পারি, সে আমাদের সাথে করেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং চূড়ান্ত সংকল্পে নিজেকে সমর্পণ করেছেন যেন সে তার ভাই হতে না দেয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ وَبِالنَّاسِ يَوْمَئِذٍ جَهْدٌ قَالَ فَمَرَّ بِنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَنَهَانَا عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏وَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ ‏","","",""],[4820,4820,"","আমরা আমার বাবাকে চিঠি লেখার সময় ঈশ্বর সম্বন্ধে কথা বলেছিলাম, যখন আমরা তাকে আরও বেশি কিছু বলেছিলাম । এমনকি গ্রেফতার হওয়ার আগেই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى طَعَامًا فَلَا يَبِيعُهُ حَتَّى يَقْبِضَهُ ‏","","",""],[4821,4821,"","আমি যখন ঘরে ফিরে আসি, তখন আমার বাবা আমাদের সাহায্য করার চেষ্টা করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ يَعْنِي الْحَنَفِيَّ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبَيْتِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[4822,4822,"","আমরা ঈশ্বরের সাথে কথা বলেছি, আমার বাবা আমাকে লিখতে বলেছেন যে আমার সাথে আবেগী রাগ আছে। সে বলেছে তোমার মেকার কথা সে আমাকে বলেছে যে সে ঈশ্বরের কাছে যাবে। বাড়িতে পৌঁছে তুমি তার সাথে শেষ হয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ الْحَنَفِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْبَيْتِ ‏ ‏وَسَتَأْتُونَ مَنْ يَنْهَاكُمْ عَنْهُ ‏","","",""],[4823,4823,"","আমরা ঈশ্বরের সাথে কথা বলেছি আমার বাবাকে লিখতে যখন আমরা বলেছিলাম যে আমরা সুখী নই, আমরা একটা ছেলেকে জিজ্ঞেস করব যে, কখন দুই মাখন আর ব্যবহার করতে হবে আমি তাকে আদেশ করেছি, ঈশ্বর আদেশ করেছেন আর তাকে মদ খাওয়া থেকে উদ্ধার করবেন। যে আমাদের ভেতরে ঢুকতে দিতে পারে না তার জন্য যুদ্ধ করতে হবে। তার প্রভুর কাছে আছে তার জন্য প্রার্থনা করতে হবে এবং সে তাকে আত্মসমর্পণ করতে ব্যর্থ হবে। সে বলল সে ঈশ্বরের কাছে প্রার্থনা করবে এবং সে আত্মসমর্পণ করবে। যতক্ষণ না পর্যন্ত ও বাতাসে ভেসে না যায়, ততক্ষণ পর্যন্ত হিংসেতে শান্তি বজায় রাখা","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏نَجْرَانَ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ إِنَّمَا أَسْأَلُكَ عَنْ اثْنَتَيْنِ عَنْ الزَّبِيبِ وَالتَّمْرِ وَعَنْ ‏ ‏السَّلَمِ ‏ ‏فِي النَّخْلِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ سَكْرَانَ فَقَالَ إِنَّمَا شَرِبْتُ زَبِيبًا وَتَمْرًا قَالَ ‏ ‏فَجَلَدَهُ الْحَدَّ وَنَهَى عَنْهُمَا أَنْ يُجْمَعَا قَالَ ‏ ‏وَأَسْلَمَ ‏ ‏رَجُلٌ فِي نَخْلٍ لِرَجُلٍ فَقَالَ لَمْ ‏ ‏تَحْمِلْ ‏ ‏نَخْلُهُ ذَلِكَ الْعَامَ فَأَرَادَ أَنْ يَأْخُذَ دَرَاهِمَهُ فَلَمْ يُعْطِهِ فَأَتَى بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَمْ ‏ ‏تَحْمِلْ ‏ ‏نَخْلُهُ قَالَ لَا قَالَ فَفِيمَ تَحْبِسُ دَرَاهِمَهُ قَالَ فَدَفَعَهَا إِلَيْهِ قَالَ وَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏السَّلَمِ ‏ ‏فِي النَّخْلِ حَتَّى ‏ ‏يَبْدُوَ ‏ ‏صَلَاحُهُ ‏","","",""],[4824,4824,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন, তিনি তা শুনেছিলেন এবং তা তিনি তা দিয়েছিলেন । বলা উচিত যে, এই অধিকারটাই সঠিক।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ وَسَأَلَهُ رَجُلٌ عَنْ الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[4825,4825,"","আমি বাবার কন্যাকে কি করে পেয়েছি সে সম্পর্কে কথা বলেছি। আমি ঈশ্বরের কাছে প্রার্থনা করবো, একবার আমি এমন একটা ছেলের কাছে যাব, যে আমার কখনো কিছু করবে না। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার কাছে প্রার্থনা করেছেন। তাকে আক্রমণ করার আগেই তাকে উদ্ধার করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ الْعُمْرَةِ قَبْلَ الْحَجِّ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا بَأْسَ عَلَى أَحَدٍ يَعْتَمِرُ قَبْلَ أَنْ يَحُجَّ قَالَ ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏اعْتَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يَحُجَّ ‏","","",""],[4826,4826,"","ঈশ্বর হয়তো মসজিদে একজন মানুষকে বলেছিলেন যে, তিনি ঈশ্বরের কাছে বলেছিলেন যে তিনি হবেন সেই ব্যক্তি যিনি হবেন । সে-ই হবে সেই লোক যে হবে সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন একজন হবে । সে-ই হবে সেই লোক যে একজন হবে, সে হবে একজন যে হবে সে-ই হবে সেই ব্যক্তি যে হবে । যে ব্যক্তি হতে পারে, দড়ির শেষ শহর এবং সূর্যকে রোষ্ট থেকে সরানোর আশাহীন করো। নবী পৌঁছে দিয়েছেন, আর তা করতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَامَ رَجُلٌ فِي ‏ ‏مَسْجِدِ الْمَدِينَةِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مِنْ أَيْنَ تَأْمُرُنَا أَنْ ‏ ‏نُهِلَّ ‏ ‏قَالَ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏قَالَ لِي ‏ ‏نَافِعٌ ‏ ‏وَقَالَ لِي ‏ ‏ابْنُ عُمَرَ ‏ ‏وَزَعَمُوا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏ ‏وَكَانَ يَقُولُ لَا أَذْكُرُ ذَلِكَ ‏","","",""],[4827,4827,"","আমি ঈশ্বরের কাছে করা ভবিষ্যদ্বাণীর এই কথাগুলো শুনেছিলাম: “আমি পিতাকে আমার সঙ্গে কথা কহিতেছি, আর তাঁহাকে কহিল, আমার পুত্ত্র আমাকে কহিল । আপনার ছেলের কাছে বলতে চাই, আপনার হৃদয় এবং আপনার দান আপনাকে না কিনে নেওয়া একটি ছেলের ছেলে যে আপনাকে বলে, সে এমন একজন ছেলে যে তোমাকে বলবে, সে তোমার হাতে আছে। তোমার ছেলে আর তোমার সেরাটা হলো কাজ","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ ‏ ‏وَزِدْتُ أَنَا لَبَّيْكَ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ لَبَّيْكَ ‏ ‏وَالرَّغْبَاءُ ‏ ‏إِلَيْكَ وَالْعَمَلُ ‏","","",""],[4828,4828,"","ঈশ্বর বলেছিলেন, আমি আমার বাবাকে লেখার সময় সাহায্য করার চেষ্টা করেছি। আমি একজন মানুষকে জিজ্ঞেস করছি, ঈশ্বর কি তার শান্তি কামনা করবেন এবং প্রতিবেশী এবং আরবদের কাছে তাকে জিজ্ঞেস করবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَسَأَلَهُ رَجُلٌ هَلْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[4829,4829,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং আমার কাছে নিজেকে উৎসর্গ করেছিলেন, যিনি আমাদের সকলের কাছে পাপ করেছেন । গাড়ির মাংস দিন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا إِلَّا ضَارِيًا أَوْ كَلْبَ مَاشِيَةٍ فَإِنَّهُ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطَانِ ‏","","",""],[4830,4830,"","আমরা আল্লাহ্‌র কথাই বলেছিলাম, বাবার বইয়ে আমরা যা বলেছি তা হল আমরা ঈশ্বরকে খুঁজে বের করার চেষ্টা করেছি। এক ছেলে বলেছে যে আমি ইতোমধ্যে তার কাজ শেষ করেছি। তারা আপনাকে সাহায্য করেছিল বলে, বাবা, আপনি যে ভবিষ্যদ্‌বাণীর মাধ্যমে তার কথা শুনেছেন এবং জিজ্ঞেস করেছিলেন, তা তারা জানতেন ও জিজ্ঞেস করেছিল । সে আল্লাহ আমার উপর হাত নাড়তে থাকে, তারপর আমার ছেলেদের কাছ থেকে শুনে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقُلْتُ ‏ ‏أَنُهِيَ عَنْ نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ قَدْ زَعَمُوا ذَاكَ فَقُلْتُ مَنْ زَعَمَ ذَاكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ زَعَمُوا ذَاكَ فَقُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَنْتَ سَمِعْتَهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَدْ زَعَمُوا ذَاكَ ‏ ‏قَالَ ‏ ‏فَصَرَفَهُ اللَّهُ تَعَالَى عَنِّي يَوْمَئِذٍ وَكَانَ أَحَدُهُمْ إِذَا سُئِلَ أَنْتَ سَمِعْتَهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَضِبَ ثُمَّ هَمَّ بِصَاحِبِهِ ‏","","",""],[4831,4831,"","আমরা বাবার বইয়ে পাওয়া ঈশ্বরের কথা নিয়ে কথা বলেছি, আমরা হয়তো ঋণের কথা বলেছি। যাদের ভয় পাই নি, তারা তাদের আর বাজানো বন্ধ করে দিচ্ছে না","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَلْيَشُقَّهُمَا ‏ ‏أَوْ لِيَقْطَعْهُمَا ‏ ‏أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[4832,4832,"","আমরা বাবার বইয়ে পাওয়া ঈশ্বরের কথাগুলো নিয়ে কথা বলেছি, আমরা হয়তো ঋণের কথা বলেছি। অবিবাহিত থাকা সত্ত্বেও, আমরা যা করেছিলাম, তা - ই করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْوَرْسِ ‏ ‏وَالزَّعْفَرَانِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ أَنَا لِلْمُحْرِمِ فَقَالَ نَعَمْ ‏","","",""],[4833,4833,"","আমরা ঈশ্বরের গল্প নিয়ে কথা বলেছি যখন আমরা তাকে বলেছিলাম আমরা তাকে বলেছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا قَالَ الرَّجُلُ لِأَخِيهِ أَنْتَ كَافِرٌ ‏ ‏أَوْ يَا كَافِرُ ‏ ‏فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهَا أَحَدُهُمَا ‏","","",""],[4834,4834,"","আর একজন ছেলে যিনি সূর্যের ওপর দিয়ে হেঁটে গিয়েছিল, তিনি জনতাকে দোষারোপ করেছিলেন, আমরা তাকে বলেছিলাম যে, তাকে যেতে হবে । তার নিজের অনুগ্রহ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ وَثَّابٍ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الْغُسْلِ يَوْمَ الْجُمُعَةِ قَالَ فَقَالَ ‏ ‏أَمَرَنَا بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4835,4835,"","আমরা আল্লাহ্‌র সাথে কথা বলেছিলাম যে আমি আমার বাবাকে লিখতে পারি যখন আমরা একটি ছেলে কে হত্যা করার চেষ্টা করি যে ছেলে ঈশ্বরকে হত্যা করতে চেয়েছিল, সে বলল যে ঈশ্বর তার জন্য প্রার্থনা করছে এবং সে জানে ভাল মানুষের মতই আত্মসমর্পণ করো, এটা একবার আর কখনো চলে যায় না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ ‏ ‏كَمَثَلِ ‏ ‏الشَّاةِ ‏ ‏الْعَائِرَةِ ‏ ‏بَيْنَ الْغَنَمَيْنِ ‏ ‏تَعِيرُ ‏ ‏إِلَى هَذِهِ مَرَّةً وَإِلَى هَذِهِ مَرَّةً لَا تَدْرِي أَهَذِهِ تَتْبَعُ أَمْ هَذِهِ ‏","","",""],[4836,4836,"","আমরা আমার বাবার ব্যাপারে কথা বলেছি আর আমি দুঃখিত যে সে তাকে খুন করার চেষ্টা করছে। সে ডিজাইন করে নি এবং আমি তার স্বপ্নের মধ্যে টেনে নিয়ে এসেছি। দুই বছর আগে আমি একটা ছেলেকে জিজ্ঞেস করবো যে পাশ হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏وَسُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ ‏ ‏حَجَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَحَجَجْتُ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَحَجَجْتُ مَعَ ‏ ‏عُمَرَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَحَجَجْتُ مَعَ ‏ ‏عُثْمَانَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَأَنَا لَا أَصُومُهُ وَلَا آمُرُ بِهِ وَلَا أَنْهَى عَنْهُ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً عَمَّنْ سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏","","",""],[4837,4837,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি প্রার্থনা করলে তাঁর হাত ফিরে আসবেন এবং তাঁর প্রভুর কাছে ফিরে আসবেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ إِذَا دَخَلَ إِلَى الصَّلَاةِ وَإِذَا رَكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَلَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ ‏","","",""],[4838,4838,"","আমরা আমাদের পক্ষ থেকে কথা বলেছিলাম তিনি আপনার একজন ছেলে যিনি আপনার সবচেয়ে অন্ধকার মধ্যে দিয়ে গিয়েছিলেন আমি এর সাথে শান্ত আছি এবং সকালে তার প্রতি প্রার্থনা করি এবং এটা ঘটে যে আমি হতে পারি ঈশ্বরের কাছে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا دَخَلَ أَدْنَى ‏ ‏الْحَرَمِ ‏ ‏أَمْسَكَ عَنْ التَّلْبِيَةِ ثُمَّ يَأْتِي ‏ ‏ذَا طُوًى ‏ ‏فَيَبِيتُ بِهِ وَيُصَلِّي بِهِ صَلَاةَ الصُّبْحِ وَيَغْتَسِلُ وَيُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ذَلِكَ ‏","","",""],[4839,4839,"","আমরা আমাদের সাহায্য করার কথা বলেছিলাম, যে কিনা আমার কথা শুনেছে, সে বলল আমি যদি তোমাকে চ্যালেঞ্জ করি, আমি তোমাকে জনতার কাছে ভিক্ষা চাইতে বাধ্য করবো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[4840,4840,"","আমরা কথা বলেছি একটি ছেলে কি করবে যে ভবিষ্যদ্বাণীকৃত ছেলেকে ঈশ্বরের কাছে পেশ করা হয়েছে. যে বজ্র হারিয়েছে তার মানে হচ্ছে আমি বিক্ষিপ্ত হয়ে গেছি আর তার টাকা এখন তার টাকা টাকা দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الَّذِي يَفُوتُهُ الْعَصْرُ كَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[4841,4841,"","আমরা আমাদের কথা বলেছি একটি ছেলে জন্য ভাল কিছু করতে পারে কিনা, যে কিনা কিনা বলা হয়েছে যে কিনা কিনা প্রার্থনা করছিল। তিনি বললেন, \"ঈশ্বর, তুমি আমাদের রাতের এক রাতের প্রার্থনা করতে বলো।\" তিনি বললেন, \"ঈশ্বর, তুমি কীভাবে আমাদের আদেশ দিতে পারো?\" আপনি দুটো পাপের জন্য প্রার্থনা করেন, কখনও প্রার্থনা করেন নি","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ كَيْفَ تَأْمُرُنَا نُصَلِّي مِنْ اللَّيْلِ قَالَ ‏ ‏يُصَلِّي أَحَدُكُمْ مَثْنَى مَثْنَى فَإِذَا خَشِيَ الصُّبْحَ ‏ ‏يُصَلِّي وَاحِدَةً ‏ ‏فَأَوْتَرَتْ ‏ ‏لَهُ مَا قَدْ صَلَّى ‏","","",""],[4842,4842,"","আমরা কথা বলেছি, জন্ম নিয়ে কি করতে হবে তা আমাদের বলতে হবে। আপনার বাবা আপনার কাছে আপনার বাবার অনুগ্রহ এবং অনুগ্রহ আপনার জন্য আপনার বাবার কাছে নয় বরং আপনার বাবার প্রতি আপনার অনুগ্রহ এবং অনুগ্রহ আছে আপনার প্রতি. তোমার কাছে কখনো যাইনি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ تَلْبِيَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4843,4843,"","আমি গর্ভবতী হয়ে এবং জীবিতদের সবচেয়ে খারাপ কথা বলছি এবং আমি সঠিক কাজটি করি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مِنْ أَيْنَ ‏ ‏نُهِلُّ ‏ ‏قَالَ ‏ ‏يُهِلُّ ‏ ‏أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَأَهْلُ ‏ ‏الشَّأْمِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَأَهْلُ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏قَالَ وَيَقُولُونَ وَأَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[4844,4844,"","আমরা মানুষকে ভালো করে সাহায্য করার কথা বলেছিলাম, তারপর দেখা যাবে যে এই মানুষটি লর্ড হওয়ার পর তাকে এটা করতে হবে আর সে বলবে যে, গামটা হচ্ছে একমাত্র সাথ তাকে দেয়া হয়েছে, আগামীকাল ঈশ্বরের ইচ্ছার সাথে মিল রেখে নয় যে সে হবে তার ভয় পাবে। তুমি আমার ছেলের চেয়ে ভাল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏صَخْرُ بْنُ جُوَيْرِيَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَلَعَ النَّاسُ ‏ ‏يَزِيدَ بْنَ مُعَاوِيَةَ ‏ ‏جَمَعَ ‏ ‏ابْنُ عُمَرَ ‏ ‏بَنِيهِ وَأَهْلَهُ ثُمَّ تَشَهَّدَ ثُمَّ قَالَ أَمَّا بَعْدُ فَإِنَّا قَدْ بَايَعْنَا هَذَا الرَّجُلَ عَلَى بَيْعِ اللَّهِ وَرَسُولِهِ وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الْغَادِرَ ‏ ‏يُنْصَبُ لَهُ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ يُقَالُ هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ وَإِنَّ مِنْ أَعْظَمِ الْغَدْرِ أَنْ لَا يَكُونَ الْإِشْرَاكُ بِاللَّهِ تَعَالَى أَنْ يُبَايِعَ رَجُلٌ رَجُلًا عَلَى بَيْعِ اللَّهِ وَرَسُولِهِ ثُمَّ يَنْكُثَ بَيْعَتَهُ فَلَا يَخْلَعَنَّ أَحَدٌ مِنْكُمْ يَزِيدَ وَلَا يُشْرِفَنَّ أَحَدٌ مِنْكُمْ فِي هَذَا الْأَمْرِ فَيَكُونَ صَيْلَمٌ بَيْنِي وَبَيْنَهُ ‏","","",""],[4845,4845,"","আমি বলেছিলাম একটা নির্দিষ্ট দোকানে একজন মানুষকে খুঁজে পেতে আমাকে সাহায্য করা হয়েছে, আমি আল্লাহ্‌কে প্রার্থনা করেছি এবং পৃথিবী দিয়ে তার মুক্তির জন্য আমাকে তা দিতে হবে। আমি বলেছিলাম, তিনি আমাকে বললেন না। আমি এটা করতে নয়। আমি জানি, আমি জানি, আমি কি করেছি। আমি এটা আমার কাছে এটা একটা বড় দোকান আছে? আমি জানি, আমি কি করেছি? আমি জানি, আমি এটা আমার মনে করি, আমি এটা একটা জিনিস আছে? আমি কি জানি না। আমি এটা আমার কাছে এটা একটা ছোট জিনিস আছে? আমি কি জানি? আমি এটা একটা ছোট জিনিস আছে? আমি কি জানি? আমি কি করি? আমি জানি না? আমি এটা কি করেছি? আমি জানি না? আমি জানি না? আমি এটা আমার কাছে এটা আমার কাছে এটা একটা জিনিস আছে? আমি কি করবো? আমি এটা আমার কাছে এটা আমার জীবনের ব্যাপার। আমি শুধু একটা ছোট কাজ করে না। আমি কি করব? আমি কি করবো? আমি কি করব? আমি এটা আমার কাছে এটা একটা জিনিস আছে? ঈশ্বর হয়তো বলতে পারেন যে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আপনার জন্য আত্মসমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏فِي مَجْلِسِ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏فُلَانٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِطَعَامٍ مِنْ خُبْزٍ وَلَحْمٍ فَقَالَ نَاوِلْنِي الذِّرَاعَ فَنُووِلَ ذِرَاعًا فَأَكَلَهَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏لَا أَعْلَمُهُ إِلَّا هَكَذَا ‏ ‏ثُمَّ قَالَ نَاوِلْنِي الذِّرَاعَ فَنُووِلَ ذِرَاعًا فَأَكَلَهَا ثُمَّ قَالَ نَاوِلْنِي الذِّرَاعَ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّمَا هُمَا ذِرَاعَانِ فَقَالَ وَأَبِيكَ لَوْ سَكَتَّ مَا زِلْتُ أُنَاوَلُ مِنْهَا ذِرَاعًا مَا دَعَوْتُ بِهِ فَقَالَ ‏ ‏سَالِمٌ ‏ ‏أَمَّا هَذِهِ فَلَا سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ ‏","","",""],[4846,4846,"","তিনি ঈশ্বর তার ইচ্ছা অস্বীকার করেছেন এবং কেন আমি তা শুনেছি, সেই বিষয়ে আমার জ্ঞান আছে । সে তার সর্বোচ্চ চেষ্টা করেছে। সে যা বলেছে, আমি তার সর্বোচ্চ মুখ দিয়ে তাকে শপথ করে বলছি। আর তাকে বলা হয়েছে গাছের আগুন নেভানোর জন্য। ঈশ্বর তাকে আত্মসমর্পণ করেছেন এবং প্রতিবেশী যখন সব কিছু বলেন তখন তিনি তাকে উদ্ধার করেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَسُئِلَ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ ‏ ‏حَرَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَقَّ عَلَيَّ لَمَّا سَمِعْتُهُ فَأَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ إِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏سُئِلَ عَنْ شَيْءٍ قَالَ فَجَعَلْتُ أُعَظِّمُهُ فَقَالَ وَمَا هُوَ قُلْتُ سُئِلَ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ حَرَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ صَدَقَ حَرَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ وَمَا ‏ ‏الْجَرُّ ‏ ‏قَالَ ‏ ‏كُلُّ شَيْءٍ صُنِعَ مِنْ ‏ ‏مَدَرٍ ‏","","",""],[4847,4847,"","আমরা আমাদের কথা বলেছিলাম যে ছেলে কি করবে, প্রভু, আমরা যা করছি তা না করার জন্য, আমাকে পাঁচ বছর ধরে হত্যা করতে নিষেধ করা হয়েছে, যুদ্ধ করতে নয়, হত্যা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ مَا نَقْتُلُ مِنْ الدَّوَابِّ إِذَا أَحْرَمْنَا فَقَالَ ‏ ‏خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى مَنْ قَتَلَهُنَّ فِي قَتْلِهِنَّ الْحِدَأَةُ وَالْفَأْرَةُ وَالْغُرَابُ وَالْعَقْرَبُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏","","",""],[4848,4848,"","আমি যা বলেছি, ঈশ্বর সেই নকশা থেকে নিজেকে আত্মসমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى النَّاسِ وَقَدْ فَرَغَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْخُطْبَةِ فَقُلْتُ مَاذَا قَامَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[4849,4849,"","আমরা একটা পাথর পরিবর্তন করেছি, আমরা আমার ছেলে কিভাবে কাজ করতো সে সম্পর্কে কথা বলেছি। আপনার মন ঠিক করুন,","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ ‏ ‏فَاسْتَثْنَى ‏ ‏فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏إِنْ شَاءَ أَنْ يَمْضِيَ عَلَى يَمِينِهِ وَإِنْ شَاءَ أَنْ يَرْجِعَ ‏ ‏غَيْرَ ‏ ‏حَنِثٍ ‏ ‏أَوْ قَالَ غَيْرَ حَرَجٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا حَلَفَ أَحَدُكُمْ فَذَكَرَهُ ‏","","",""],[4850,4850,"","আমরা আমার বাবার সাথে কথা বলেছি, তিনি বলেছেন যে লেখক তৃতীয়বারের মতো একটা উৎক্ষেপণের মধ্যে আছেন, প্রভু, যদি না মরে যায়, তবে যদি তিনি লেকটা না যান বা চলে না যান। সে বলেছে সে কখনো করেনি, ঈশ্বর এটা করেছেন এবং সে এটা করেছে। ঈশ্বর আপনার কথা শুনে শুনেও আপনার কথা শোনা যায় যে তিনি এমন নন যে তিনি কখনও করেছেন। কিন্তু আমি তোমাকে গুলি করতে খুজে পেলাম আর তারপর তাকে বলে দিলাম, ক্যাঙ্গারেনে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏فِي سُوقٍ ثَوْبًا مِنْ ‏ ‏إِسْتَبْرَقٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ لَوْ ابْتَعْتَ هَذَا الثَّوْبَ لِلْوَفْدِ قَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ ‏ ‏أَوْ قَالَ هَذَا ‏ ‏مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏ ‏قَالَ أَحْسِبُهُ قَالَ فِي الْآخِرَةِ ‏ ‏قَالَ فَلَمَّا كَانَ بَعْدَ ذَاكَ أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَوْبٍ مِنْهَا فَبَعَثَ بِهِ إِلَى ‏ ‏عُمَرَ ‏ ‏فَكَرِهَهُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ بَعَثْتَ بِهِ إِلَيَّ وَقَدْ قُلْتَ فِيهِ مَا سَمِعْتُ إِنَّمَا يَلْبَسُ الْحَرِيرَ ‏ ‏أَوْ قَالَ هَذَا ‏ ‏مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ قَالَ إِنِّي لَمْ أَبْعَثْ بِهِ إِلَيْكَ لِتَلْبَسَهُ وَلَكِنْ بَعَثْتُ بِهِ إِلَيْكَ لِتُصِيبَ بِهِ ثَمَنًا ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏فَمِنْ أَجْلِ هَذَا الْحَدِيثِ كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَكْرَهُ ‏ ‏الْعَلَمَ ‏ ‏فِي الثَّوْبِ ‏","","",""],[4851,4851,"","আমরা সাক্ষীর ছেলেকে ভালোবাসার কথা বলেছিলাম যিনি আমার বাবার সাথে কথা বলেছিলেন ভুলে যান যে তিনি এটা করেছেন। আমার ছেড়ে চলে যাওয়া উচিত ছিল তাকেই বহিষ্কার করা, যে ছিল সেই সেই ব্যক্তি যে ছিল সেই সেই ব্যক্তি, যে কিনা সেই। যে ই একমাত্র সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি, যিনি ছিলেন সেই ব্যক্তি । আমি বলছি, রাতে আমি তোমাকে ছেড়ে দেবো। ঈশ্বরের জন্য প্রার্থনা করছি, আর দিনের জন্য, আনন্দ অথবা আনন্দের ভয়ে। আপনি বলেছিলেন যে, ঘুম না করে যদি বলেন যে, তিনি তা করবেন না, তাহলে আপনি ঘুম থেকে উঠে যাবেন । আমি মুলহামের সামনে বসে থাকতাম, বলেছিল যে এটা একটা স্বপ্ন ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَقْرَأُ خَلْفَ الْإِمَامِ قَالَ تُجْزِئُكَ قِرَاءَةُ الْإِمَامِ قُلْتُ رَكْعَتَيْ الْفَجْرِ أُطِيلُ فِيهِمَا الْقِرَاءَةَ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ اللَّيْلِ مَثْنَى مَثْنَى قَالَ قُلْتُ إِنَّمَا سَأَلْتُكَ عَنْ رَكْعَتَيْ الْفَجْرِ قَالَ إِنَّكَ ‏ ‏لَضَخْمٌ ‏ ‏أَلَسْتَ تَرَانِي أَبْتَدِئُ الْحَدِيثَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيَ الصُّبْحَ ‏ ‏أَوْتَرَ ‏ ‏بِرَكْعَةٍ ثُمَّ يَضَعُ رَأْسَهُ فَإِنْ شِئْتَ قُلْتَ نَامَ وَإِنْ شِئْتَ قُلْتَ لَمْ يَنَمْ ثُمَّ يَقُومُ إِلَيْهِمَا وَالْأَذَانُ فِي أُذُنَيْهِ فَأَيُّ طُولٍ يَكُونُ ثُمَّ قُلْتُ رَجُلٌ أَوْصَى بِمَالٍ فِي سَبِيلِ اللَّهِ أَيُنْفَقُ مِنْهُ فِي الْحَجِّ قَالَ أَمَا إِنَّكُمْ لَوْ فَعَلْتُمْ كَانَ مِنْ سَبِيلِ اللَّهِ قَالَ قُلْتُ رَجُلٌ تَفُوتُهُ رَكْعَةٌ مَعَ الْإِمَامِ فَسَلَّمَ الْإِمَامُ أَيَقُومُ إِلَى قَضَائِهَا قَبْلَ أَنْ يَقُومَ الْإِمَامُ قَالَ كَانَ الْإِمَامُ إِذَا سَلَّمَ قَامَ قُلْتُ الرَّجُلُ يَأْخُذُ بِالدَّيْنِ أَكْثَرَ مِنْ مَالِهِ قَالَ لِكُلِّ ‏ ‏غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ عِنْدَ اسْتِهِ عَلَى قَدْرِ ‏ ‏غَدْرَتِهِ ‏","","",""],[4852,4852,"","আমি ঈশ্বরের পুত্রদের নিয়ে কথা বলেছি আমার ছেলে হওয়ার দুই মাস পর, আমি ভাববাদীর কাছে প্রার্থনা করেছিলাম, তিনি আমার বাবার স্বপ্নের কথা আর তার বাবার স্বপ্নের কথা আমার স্বপ্নের কথা ভুলে গেছেন। বাবা, আমরা দুই বছর ধরে একটা ছেলেকে নিয়ে কাজ করেছি, সে সৃষ্টিকর্তা হয়েছে। আমি এটা করেছি, যেন সে আমাদের হাতের হাতের সাথে বাস করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏جَهْضَمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَدْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَحْلِلْ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏فَلَمْ يَحِلُّوا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ فَعَلَ ذَلِكَ مِثْلَ حَدِيثِ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏فِي رَفْعِ الْيَدَيْنِ ‏","","",""],[4853,4853,"","আমরা ঈশ্বরের ছেলেদের কথা বলেছিলাম তারা আমার হাত দিয়ে আমাকে কথা বলার চেষ্টা করছে। এক ছেলে বলল, আমি ভাববাদীকে প্রার্থনা করতে দেখলাম এবং পাথরের জন্য প্রার্থনা করতে দেখলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ يَحْيَى الْمَازِنِيُّ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى حِمَارٍ وَهُوَ مُتَوَجِّهٌ إِلَى ‏ ‏خَيْبَرَ ‏","","",""],[4854,4854,"","আমরা ঈশ্বরের ছেলেদের কথা বলেছিলাম আমার বাবার সাথে এমন হয়েছে, সে ঈশ্বরের কাছে প্রার্থনা করেছে, তোমার সেবা দ্বারা আর বিচার করা হবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغْلِبَنَّكُمْ ‏ ‏الْأَعْرَابُ ‏ ‏عَلَى اسْمِ صَلَاتِكُمْ إِنَّهُمْ يُعْتِمُونَ عَلَى الْإِبِلِ إِنَّهَا صَلَاةُ الْعِشَاءِ ‏","","",""],[4855,4855,"","আমরা ঈশ্বরের পুত্রদের কথা বলেছিলাম... ...যে জিনিয়াস ছিল... ...সে তার জন্য প্রার্থনা করেছে আর তার ছেলের মঙ্গলের জন্য তাদের পাপ সমর্পণ করবে. \"ঈশ্বরের বার্তাবাহক\" তাকে পৌঁছে দিত... ...আর তুমি বলতে না যে তুমি না.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏وَلَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنُوا لِلنِّسَاءِ بِاللَّيْلِ إِلَى الْمَسَاجِدِ ‏ ‏فَقَالَ ‏ ‏ابْنُهُ لَا نَأْذَنُ لَهُنَّ يَتَّخِذْنَ ذَلِكَ ‏ ‏دَغَلًا ‏ ‏فَقَالَ ‏ ‏تَسْمَعُنِي أَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ أَنْتَ لَا ‏","","",""],[4856,4856,"","কল্পনায় পড়ে যাওয়া কল্পনাটা তার শেষ বীর্য ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[4857,4857,"","আমরা ঈশ্বরের কাছে আমার সেরাদের কাছে কথা বলেছি, যে ছেলে তার শান্তি লাভ করেছে আর তাকে আত্মসমর্পণ করবে দুই বার তুমি মিথ্যা বলবে তোমার আগে যত হাঁটু ছিল, সব ঠিক আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ يَعْنِي أَبَا أَحْمَدَ الزُّبَيْرِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ صَلَاةِ اللَّيْلِ فَقَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى تُسَلِّمُ فِي كُلِّ رَكْعَتَيْنِ فَإِذَا خِفْتَ الصُّبْحَ فَصَلِّ رَكْعَةً ‏ ‏تُوتِرُ ‏ ‏لَكَ مَا قَبْلَهَا ‏","","",""],[4858,4858,"","আমরা ঈশ্বরের প্রভুর দিনের একটা নির্দিষ্ট কথা বলেছি, কিন্তু আমরা একটি ছেলের জন্য একটা উপকার করেছি, যে তার কাছে বানানো হয়েছে। আমি বলেছিলাম, এই দর্শন হচ্ছে বিশুদ্ধিকরণের সাতটি অবজার্তির অংশ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[4859,4859,"","আমরা ঈশ্বরের গলা ধরে রাখার চেষ্টা করেছি, ঈশ্বরের জীবনের পাপের জন্য বাবার পাপ আমরা করেছি। পৃথিবীর শক্তি দিয়ে, যতক্ষণ না তুমি ধনী হও.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ سُرَاقَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثِّمَارِ حَتَّى تَذْهَبَ ‏ ‏الْعَاهَةُ ‏ ‏قُلْتُ وَمَتَى ذَاكَ قَالَ حَتَّى تَطْلُعَ ‏ ‏الثُّرَيَّا ‏","","",""],[4860,4860,"","আমরা ঈশ্বরের দোহাই দিয়ে দুইটা জীবন দিয়েছি ঈশ্বরের ছেলের উপর আমরা করতে পারি, আল্লাহ আমাদের উদ্ধার করতে হবে, যারা ভয় পায় না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ يَقْطَعُهُمَا حَتَّى يَكُونَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[4861,4861,"","সে ঈশ্বরকে বলে যে, সে তার জন্য প্রার্থনা করে এবং সে আমাকে একটা অনুমান করতে পারে যে, খুন করার জন্য সে কোন স্বাধীন উপায় খুঁজে পাবে না। আর বিছানা এবং কুকুরগুলো এমন এক মানুষ, যে কখনো হয়নি।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي ‏ ‏خَمْسٌ لَا جُنَاحَ عَلَيْهِ وَهُوَ حَرَامٌ أَنْ يَقْتُلَهُنَّ الْحَيَّةُ وَالْعَقْرَبُ وَالْفَأْرَةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْحِدَأَةُ ‏","","",""],[4862,4862,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেন, এবং আমি তাকে ঈশ্বরের কাছে ক্ষমা প্রার্থনা করব এবং তার কাছে প্রার্থনা করব, যেন তিনি তার কাছে ক্ষমা চান এবং তার চিতাবাঘ এবং তার চিত্‍কার ও শ্বাসক আছে। এবং তিনি সেটা পাঠান।","‏ ‏و قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارُ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَعُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏","","",""],[4863,4863,"","আমরা ঈশ্বরের ভালো লোকদের দ্বারা বাপ্তাইজিত হয়েছি যারা আমাদের সাথে কথা বলেছে, কিন্তু আমি শুনেছি একটা ছেলে আছে যে ছেলে হয়েছে একটি ছেলে ছেলে পুত্র হয়েছে যে সন ্ তান গ ্ রহণ করা হয়েছে । একটি ছেলে ছেলে পুত্র হয়েছে যে সন ্ তান গ ্ রহণ করা হয়েছে , একটি ছেলে ছেলে ছেলে ছেলে হয়েছে যে সন ্ তান গ ্ রহণ করেছে , একটি ছেলে ছেলে পুত্র হয়েছে যে সন ্ তান গ ্ রহণ করা হয়েছে , যে ছেলে ছেলে হয়েছে, সে এমন এক ছেলে যে তার জন্য প্রার্থনা করেছে, যে তার কাছে ঈশ্বরের কাছে প্রার্থনা করেছে এবং তাকে আত্মসমর্পণ করেছে এবং নির্দেশ করেছে যে, এই মেয়েটি হচ্ছে সম্মানিত হত্যা করা। শয়তানের গোষ্ঠী.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَشَارَ بِيَدِهِ نَحْوَ الْمَشْرِقِ فَقَالَ هَا ‏ ‏إِنَّ ‏ ‏الْفِتَنَ ‏ ‏مِنْ هَاهُنَا إِنَّ ‏ ‏الْفِتَنَ ‏ ‏مِنْ هَاهُنَا إِنَّ ‏ ‏الْفِتَنَ ‏ ‏مِنْ هَاهُنَا مِنْ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[4864,4864,"","আমরা ঈশ্বরের দিন নিয়ে কথা বলেছি, বাবার মক্কেলের কথা বলছি, যে আমার জন্য খুশি হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَارَ لَيْلًا ‏","","",""],[4865,4865,"","আমরা ঈশ্বরের দোহাই দিয়ে বলছি, কিন্তু আমরা ঈশ্বরের অনুগ্রহের সন্তানের উপর দুইটা জীবন করেছি। ঈশ্বর তাকে দাবি করেছেন এবং অন্ধকারের মরণ কামনা করেছেন। আমি যে মেয়েদের ঈশ্বরের কাছে পাঠাতে পারি, তাকে উদ্ধার করতে হবে এবং আমি তার সাথে কথা বলেছি, এবং দোষ দেওয়ার অধিকার তার আছে, সে কোন প্রেমিক নয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَقَّتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الشَّأْمِ ‏ ‏الْجُحْفَةَ ‏ ‏وَقَالَ هَؤُلَاءِ الثَّلَاثُ حَفِظْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحُدِّثْتُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمُ ‏ ‏فَقِيلَ لَهُ ‏ ‏الْعِرَاقُ ‏ ‏قَالَ لَمْ يَكُنْ يَوْمَئِذٍ عِرَاقٌ ‏","","",""],[4866,4866,"","পাপের মাধ্যমে আমি ঈশ্বরের কাছে প্রার্থনা করতে শুনেছি যে, তিনি তা করতে পারবেন এবং বলবেন যে, ঈশ্বর আমাকে ভালোবাসেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَرْثَدٌ يَعْنِي ابْنَ عَامِرٍ الْهُنَائِيَّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَمْرٍو النَّدَبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ لَيَعْجَبُ مِنْ الصَّلَاةِ فِي الْجَمِيعِ ‏","","",""],[4867,4867,"","আমাদের ছেলে যখন মারা গিয়েছিল, তখন আমরা বাবাকে এক উত্তম ছেলের দশশ ছেলের বিষয়ে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِطَعَامٍ وَقَدْ حَسَّنَهُ صَاحِبُهُ فَأَدْخَلَ يَدَهُ فِيهِ فَإِذَا طَعَامٌ رَدِيءٌ فَقَالَ ‏ ‏بِعْ هَذَا عَلَى حِدَةٍ وَهَذَا عَلَى حِدَةٍ فَمَنْ غَشَّنَا فَلَيْسَ مِنَّا ‏","","",""],[4868,4868,"","আমরা আমাদের অবস্থা ভালো করার চেষ্টা করেছি, আমার ছেলে ঈশ্বরের কাছে প্রার্থনা করেছে তাকে উদ্ধার করতে আর তার আত্মা পাঠিয়ে দিতে হবে. কাল্পনিক এবং শিংী যে এটা দেখেছে শক্তি দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ يَعْنِي الْوَاسِطِيَّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي مُنِيبٍ الْجُرَشِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثْتُ بِالسَّيْفِ حَتَّى يُعْبَدَ اللَّهُ لَا شَرِيكَ لَهُ وَجُعِلَ رِزْقِي تَحْتَ ظِلِّ رُمْحِي وَجُعِلَ الذِّلَّةُ ‏ ‏وَالصَّغَارُ ‏ ‏عَلَى مَنْ خَالَفَ أَمْرِي وَمَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ ‏","","",""],[4869,4869,"","আমি মনে মনে মনে মনে মনে বলেছিলাম যে, আমার স্বামী আমাকে সাহায্য করতে পারবে । আমার ভাইয়ের ছায়া আমার গৌরবের ছায়া তৈরি করেছে আর তার প্রতি উজ্জ্বল হতে বাধ্য করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَابِتِ بْنِ ثَوْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي مُنِيبٍ الْجُرَشِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثْتُ بَيْنَ يَدَيْ السَّاعَةِ بِالسَّيْفِ حَتَّى يُعْبَدَ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَجُعِلَ رِزْقِي تَحْتَ ظِلِّ رُمْحِي وَجُعِلَ الذِّلَّةُ ‏ ‏وَالصَّغَارُ ‏ ‏عَلَى مَنْ خَالَفَ أَمْرِي وَمَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ ‏","","",""],[4870,4870,"","আমরা একটা ছেলেকে খুঁজে বের করার চেষ্টা করেছি যে ঈশ্বরকে রক্ষা করেছে আর শান্তি পাবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْبَيْتِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[4871,4871,"","আমরা আমার বাবার ছেলেকে বলেছিলাম যে তার বাবাকে সফল হতে সাহায্য করতে। আমার বাবার সাথে এত বেশি কথা বলতে সে বধির হবে। আমি তার ডিজাইন দুটো গণনা করে তাকে বিশ্বাস করি না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ ‏ ‏حَجَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَحَجَجْتُ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَحَجَجْتُ مَعَ ‏ ‏عُمَرَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَحَجَجْتُ مَعَ ‏ ‏عُثْمَانَ ‏ ‏فَلَمْ يَصُمْهُ ‏ ‏وَأَنَا لَا أَصُومُهُ وَلَا آمُرُ بِهِ وَلَا ‏ ‏أَنْهَى عَنْهُ ‏","","",""],[4872,4872,"","আমি যখন তাকে জিজ্ঞেস করি যে, সে যা চায়, তা করার জন্য তিনি কী করতে চান, তা নিয়ে আমি চিন্তা করি ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ يَبِيتُ لَيْلَتَيْنِ وَلَهُ مَا يُرِيدُ أَنْ يُوصِيَ فِيهِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[4873,4873,"","আমরা তাকে জিততে সাহায্য করার কথা বলেছিলাম, সে বলবে যদি আমি তাকে তার আসন না দেই। আমি বলবো আগুন থেকে আগুনের নাম বের না হওয়া পর্যন্ত এটা তোমার অবস্থান মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ أَحْسِبُهُ قَدْ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا مَاتَ أَحَدُكُمْ ‏ ‏يُعْرَضُ ‏ ‏عَلَيْهِ مَقْعَدُهُ ‏ ‏غُدْوَةً ‏ ‏وَعَشِيَّةً إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ الْجَنَّةِ وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ النَّارِ يُقَالُ هَذَا مَقْعَدُكَ حَتَّى تُبْعَثَ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4874,4874,"","আমরা আমাদের কথা বলেছিলাম রানীর ক্ষমতা নিয়ে কি করা যায়। চুপ থাকার সময় আমি তাকে স্পর্শ করেছিলাম। আল্লাহ তার কাছে প্রার্থনা করলেন যেন তিনি আত্মসমর্পণ করেন। আমি তাদের ছেলেদের সাথে দেখা করি, তারা সকাল পর্যন্ত চলে যাবে। আমরা তাদের সাথে দেখা করতে গিয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏اسْتُصْرِخَ ‏ ‏عَلَى ‏ ‏صَفِيَّةَ ‏ ‏فَسَارَ فِي تِلْكَ اللَّيْلَةِ مَسِيرَةَ ثَلَاثِ لَيَالٍ سَارَ حَتَّى أَمْسَى فَقُلْتُ الصَّلَاةَ فَسَارَ وَلَمْ يَلْتَفِتْ فَسَارَ حَتَّى أَظْلَمَ فَقَالَ لَهُ ‏ ‏سَالِمٌ ‏ ‏أَوْ رَجُلٌ ‏ ‏الصَّلَاةَ وَقَدْ أَمْسَيْتَ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا عَجِلَ بِهِ السَّيْرُ جَمَعَ مَا بَيْنَ هَاتَيْنِ الصَّلَاتَيْنِ وَإِنِّي أُرِيدُ أَنْ أَجْمَعَ بَيْنَهُمَا فَسِيرُوا فَسَارَ حَتَّى غَابَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ نَزَلَ فَجَمَعَ بَيْنَهُمَا ‏","","",""],[4875,4875,"","আমরা কাঠবিড়ালীর ছেলে, তার মহিলা তালাকপ্রাপ্তা ছেলে, আর সে একজন শপথী খুনী যে জানে সে কি করেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি তাকে আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ أَتَعْرِفُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قُلْتُ نَعَمْ قَالَ فَإِنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُرَاجِعَهَا ثُمَّ يُطَلِّقَهَا فَتَسْتَقْبِلَ عِدَّتَهَا ‏","","",""],[4876,4876,"","আমরা আবেগ নিয়ে বাপ্তাইজিত হয়েছি, একটা উপহারের ব্যাপারে যা সে আমার বাবার কথা শুনেছে। রাত আর দিনের দু’বার প্রার্থনা করি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلِيًّا الْأَزْدِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ اللَّيْلِ وَالنَّهَارِ مَثْنَى مَثْنَى ‏ ‏وَكَانَ ‏ ‏شُعْبَةُ ‏ ‏يَفْرَقُهُ ‏","","",""],[4877,4877,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের নিয়ে একটা দাঙ্গার সৃষ্টি করেছে কত বছর বয়সী ছেলে পরিবর্তন করার চেষ্টা করছে। সে ভগবানকে কিছু একটা রান্না করতে বলেছে, আর সে কোন মাগলের বন্ধু না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏مَرِضَ ‏ ‏ابْنُ عَامِرٍ ‏ ‏فَجَعَلُوا ‏ ‏يَثْنُونَ ‏ ‏عَلَيْهِ ‏ ‏وَابْنُ عُمَرَ ‏ ‏سَاكِتٌ فَقَالَ أَمَا إِنِّي لَسْتُ ‏ ‏بِأَغَشِّهِمْ لَكَ وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ لَا يَقْبَلُ صَلَاةً بِغَيْرِ طُهُورٍ وَلَا ‏ ‏صَدَقَةً ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏","","",""],[4878,4878,"","আমরা একটি ছেলের কথা বলেছিলাম যে আমি আমার বাবার মৃত্যুর জন্য যা চেয়েছিলাম, সেটা নিয়ে আমি একটা চিঠি লিখেছিলাম। প্রথম ভিডিওতে আমি আমার প্রভুর ইচ্ছা পরিবর্তন করতে পারি এবং তাকে উদ্ধার করতে পারি। আমাকে অজ্ঞান আর অজ্ঞানের ভাগ্যের কাছে আত্মসমর্পণ করে, পানি তাদের খুনিদের মেরে ফেলেছে কারণ তাদের চিন্তা অনেক দূরের ছিল.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏قَالَ ‏ ‏كَتَبْتُ إِلَى ‏ ‏نَافِعٍ ‏ ‏أَسْأَلُهُ عَنْ الدُّعَاءِ عِنْدَ الْقِتَالِ فَكَتَبَ إِلَيَّ إِنَّمَا كَانَ ذَاكَ فِي أَوَّلِ الْإِسْلَامِ قَدْ ‏ ‏أَغَارَ ‏ ‏نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏بَنِي الْمُصْطَلِقِ ‏ ‏وَهُمْ ‏ ‏غَارُّونَ ‏ ‏وَأَنْعَامُهُمْ تُسْقَى عَلَى الْمَاءِ فَقَتَلَ مُقَاتِلَتَهُمْ ‏ ‏وَسَبَى ‏ ‏ذُرِّيَّتَهُمْ وَأَصَابَ يَوْمَئِذٍ ‏ ‏جُوَيْرِيَةَ ابْنَةَ الْحَارِثِ ‏ ‏حَدَّثَنِي بِذَلِكَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَكَانَ فِي ذَلِكَ الْجَيْشِ ‏","","",""],[4879,4879,"","আমরা একটা রীতি আর প্রচেষ্টা নিয়ে কথা বলেছি যেটা আমাকে তোমার জন্য একটা রীতির কথা শুনতে বাধ্য করেছে, ঈশ্বর তার ইচ্ছার উপর প্রভুত্ব অর্জন করেছেন. এটা নয়. এটা কে জানে. এটা আমাদের জন্য, এটা ছিল আমার নিয়ম-কানুন. আমি যা তুমি শুনতে চাই. আমি এটা শুধু তোমার জন্য. আমি বলতে চাই. আমি এটা বলতে চাই. আমি এটা বলতে পারি, তুমি এটা আমার জন্য ভাল. আমি কি বলছি না. আমি এটা শুধু তোমার জন্য. আমি এটা করতে পারি. আমি কি তোমার জন্য নয় যে তুমি এটা আমার জন্য ভাল কিছু. আমি কি করতে পারি? তুমি জানো না. আমি এটা তোমার জন্য ভাল কাজ. আমি কি করতে পারি না. আমি জানি না. আমি এটা তোমার জন্য ভাল কিছু. আমি কি তোমার জন্য ভাল কিছু করতে পারি না. আমি এটা তোমার জন্য ভাল কাজ. সে চুরি করছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَبِشْرِ بْنِ الْمُحْتَفِزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي الْحَرِيرِ ‏ ‏إِنَّمَا يَلْبَسُهُ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[4880,4880,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা একসাথে একটা রীতি নিয়ে এসেছি... ...আর একটা গানের সাথে কথা বলার দরকার, যে ভাববাদীর কাছে প্রার্থনা করে, আর বলে সে পাতা বলে শেষ পর্যন্ত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَسَمِعْتُ ‏ ‏أَبَا مِجْلَزٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْوَتْرُ ‏ ‏رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[4881,4881,"","আমরা একটি দাঙ্গা সম্পর্কে কথা বলেছি, যা আমাকে নম্রতা গড়ে তুলতে সাহায্য করেছে। তিনি তার আলোচনায় বলেছেন, ঈর্ষাপরায়ণ বেন বলেছিলেন তিনি একটা ছেলেকে শুনেছেন। সে যদি তার কাছে প্রার্থনা করত, সে ল্যাডারকে সন্ধ্যার আগে যেতে না দিতে দেবে এবং সকালে ফিরে যেতে দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ سَلْمَانَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ سَلْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّتِي لَا يَدَعُ ‏ ‏رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ وَرَكْعَتَيْنِ قَبْلَ الصُّبْحِ ‏","","",""],[4882,4882,"","আমরা আবেগ নিয়ে কথা বলেছি আর বাবার গলা শোনার ব্যাপারে আমরা কথা বলেছি। আত্মসমর্পণ করুন","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ وَثَّابٍ ‏ ‏أَنَّهُ ‏ ‏سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الْغُسْلِ يَوْمَ الْجُمُعَةِ فَقَالَ ‏ ‏أَمَرَنَا بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4883,4883,"","আমরা উৎসাহ নিয়ে কথা বলেছি... ...এক সপ্তাহ ধরে বাবার গলা... ...এক লোকের গলা শোনার জন্য... ...এক সপ্তাহ পর বাবাকে খুন করা হয়েছে. স্বপ্ন হলো ভালোবাসা আর ভালোবাসা তৈরি করা। সে এমন একজনকে দিল যে মাখন খেয়ে তার হৃদয়ের ভিতর দিয়ে চলে যেত। হৃদয়ের কাছে সে বলেছে তাকে তার মন দিতে হবে, সে তার সব টাকা দিয়ে বলেছে তাকে গুলি করে তার শেষ করতে হবে আর মইটা শেষ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ أَهْلِ ‏ ‏نَجْرَانَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قُلْتُ إِنَّمَا أَسْأَلُكَ عَنْ شَيْئَيْنِ عَنْ ‏ ‏السَّلَمِ ‏ ‏فِي النَّخْلِ وَعَنْ الزَّبِيبِ وَالتَّمْرِ فَقَالَ أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ ‏ ‏نَشْوَانَ ‏ ‏قَدْ شَرِبَ زَبِيبًا وَتَمْرًا قَالَ ‏ ‏فَجَلَدَهُ الْحَدَّ وَنَهَى أَنْ يُخْلَطَا قَالَ ‏ ‏وَأَسْلَمَ ‏ ‏رَجُلٌ فِي نَخْلِ رَجُلٍ فَلَمْ ‏ ‏يَحْمِلْ ‏ ‏نَخْلُهُ قَالَ فَأَتَاهُ يَطْلُبُهُ قَالَ فَأَبَى أَنْ يُعْطِيَهُ قَالَ فَأَتَيَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَحَمَلَتْ ‏ ‏نَخْلُكَ قَالَ لَا قَالَ فَبِمَ تَأْكُلُ مَالَهُ قَالَ فَأَمَرَهُ فَرَدَّ عَلَيْهِ وَنَهَى عَنْ ‏ ‏السَّلَمِ ‏ ‏فِي النَّخْلِ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[4884,4884,"","আমরা একটা আবেগ নিয়ে কথা বলেছি... ...যে আমরা লর্ডের কাছে আগুনের পুত্রর ঋণ নিয়ে এসেছি, ঈশ্বরের আছে এবং সবাই ভাইয়ের নামে আত্মসমর্পণ করবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ بَيِّعَيْنِ فَلَا بَيْعَ بَيْنَهُمَا حَتَّى يَتَفَرَّقَا إِلَّا بَيْعُ ‏ ‏الْخِيَارِ ‏","","",""],[4885,4885,"","আমরা আবেগ-অনুভূতি নিয়ে কথা বলেছি এবং আমরা ঈশ্বরের শক্তিশালী ঋণের কথা বলেছি। আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে , আর তার অন ্ তরের মাঝে আছে ন ্ যায়ের মৃত ্ যু । মাটি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوَرْسِ ‏ ‏وَالزَّعْفَرَانِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ لَهُ ‏ ‏يَعْنِي الْمُحْرِمَ قَالَ نَعَمْ ‏","","",""],[4886,4886,"","আমরা একটা আবেগ নিয়ে কথা বলেছি, আমরা প্রভুর ঋণের কথা শুনেছি... ...একজন কামনার ছেলে তার কথা শুনে, ঈশ্বরকে একটা পঞ্চম সুযোগ দিতে হবে, যাতে সে তাদের সবাইকে হত্যা করতে না পারে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ لَيْسَ عَلَى حَرَامٍ جُنَاحٌ فِي قَتْلِهِنَّ الْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْغُرَابُ وَالْحُدَيَّا وَالْفَأْرَةُ وَالْحَيَّةُ ‏","","",""],[4887,4887,"","আমরা আমার সবচেয়ে ভালো ছেলেকে নিয়ে কথা বলেছি ঈশ্বরের পুত্রের জন্য দুই বছর ঋণের জন্য। সে পাঁচ বছরের বোকামির সুযোগ পাবে। ঈশ্বর জানেন আমি কি করবো না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَفَاتِيحُ الْغَيْبِ خَمْسٌ لَا يَعْلَمُهُنَّ إِلَّا اللَّهُ لَا يَعْلَمُ مَا فِي غَدٍ إِلَّا اللَّهُ وَلَا يَعْلَمُ نُزُولَ ‏ ‏الْغَيْثِ ‏ ‏إِلَّا اللَّهُ وَلَا يَعْلَمُ مَا فِي الْأَرْحَامِ إِلَّا اللَّهُ وَلَا يَعْلَمُ السَّاعَةَ إِلَّا اللَّهُ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ ‏","","",""],[4888,4888,"","আমরা ঈশ্বরের ছেলের সবচেয়ে ভালো দুই তলোয়ারের কথা বলেছি। সে বলছে, সে ঈশ্বরের সন্তান হতে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُبَاعَ الثَّمَرَةُ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[4889,4889,"","ঈশ্বরের কাছে প্রার্থনা করা এক পুত্র ঈশ্বরের কাছে প্রার্থনা করেছিল এবং প্রভু ও প্রভুকে রক্ষা করা হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏هُوَ ‏ ‏ابْنُ عَلْقَمَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْفُوا اللِّحَى وَحُفُّوا الشَّوَارِبَ ‏","","",""],[4890,4890,"","আমার মনে হয়েছিল যেন আমি সত্য খুঁজে পেয়েছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَحَرَّقَ ‏","","",""],[4891,4891,"","আমরা দুটো জীবন নিয়ে কথা বলেছি আর আমি নিচে নামবো আর বলে যাব যে আমরা যেতে হবে, যে ভবিষ্যৎে পা দিয়েছে, যে ছেলে ঈশ্বরের কাছে প্রার্থনা করেছে, সে আমাদের মাকে শপথ না নিতে বাধ্য করেছে। আর তাই তিনি যখন বড় হতে বলেছিলেন এবং দশ জন তার হাত ধরে রাখার চেষ্টা করেছিলেন, তখন তিনি তিন বার হাত দিয়ে তাকে স্পর্শ করার চেষ্টা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَإِسْحَاقُ يَعْنِي الْأَزْرَقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّا أُمَّةٌ أُمِّيَّةٌ لَا نَكْتُبُ وَلَا نَحْسُبُ الشَّهْرُ هَكَذَا وَهَكَذَا حَتَّى ذَكَرَ تِسْعًا وَعِشْرِينَ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏وَطَبَّقَ يَدَيْهِ ثَلَاثَ مَرَّاتٍ وَحَبَسَ إِبْهَامَهُ فِي الثَّالِثَةِ ‏","","",""],[4892,4892,"","আমরা আশা করছি বেনের কথা শোনা ছেলের কথা আমরা দু’বছরের কথা বলেছি যে সে দেখেছে, ঈশ্বরের কাছে হার মানতে হবে এবং ঈশ্বরের কাছে প্রার্থনা করতে হবে। ( যোহন ১৭: ৩) ঈশ্বর যে জন্ম নেবেন, তা হবেই ।","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَلْقَمَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُعْفَى اللِّحَى وَأَنْ تُجَزَّ الشَّوَارِبُ ‏ ‏و قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَلْقَمَةَ ‏","","",""],[4893,4893,"","আমরা ঈশ্বরের দিন সম্বন্ধে সবচেয়ে ভালো কথা বলেছি, তিনি বলেছিলেন, \"ঈশ্বর, আমি তার মধ্যে যা করি তা আমি দেখছি।\" এটা করা হয়েছে, ছেলে, এটাও করা হয়, এপার্টমেন্ট.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ مَا نَعْمَلُ فِيهِ أَفِي أَمْرٍ قَدْ فُرِغَ مِنْهُ أَوْ مُبْتَدَإٍ أَوْ مُبْتَدَعٍ قَالَ ‏ ‏فِيمَا قَدْ فُرِغَ مِنْهُ فَاعْمَلْ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ كُلًّا مُيَسَّرٌ أَمَّا مَنْ كَانَ مِنْ أَهْلِ السَّعَادَةِ فَإِنَّهُ يَعْمَلُ لِلسَّعَادَةِ وَأَمَّا مَنْ كَانَ مِنْ أَهْلِ الشَّقَاءِ فَإِنَّهُ يَعْمَلُ لِلشَّقَاءِ ‏","","",""],[4894,4894,"","আমি একটা ঘরে গিয়েছিলাম, যেখানে ঈশ্বর সম্বন্ধে বলার বিষয়ে কথা বলতে না বলতে এবং তাকে বলতে বলেছিলেন যে তিনিই হলেন সেই ব্যক্তি । সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি তাকে বলেছিলেন । আর তিনি সেই লোকেদের সমর্পণ করিবেন, যারা তোমাদিগকে বলিবে, তোমরা আমার পশ্চাৎ আসিতেছ না; পরে তিনি আপন আপন মনেরুকে ভুলে গেলেন, এবং আপন চক্ষু হারিয়ে ফেলিলেন । ( মথি ৬: ৯) এই ভোজ ঈশ্বরের সমর্থ হওয়ার জন্য শক্তি পেতে পারে বলে ঈশ্বর অনুরোধ করেন । তিনি একজন মানুষ হতে সক্ষম হতে সক্ষম হতে সক্ষম। \"আগ, মানুষের কাছে প্রার্থনা কর, সে বলেছিল তুমি এটা পাবে।\" সে একটা পাগল হয়ে যাবে তার মনের চোখ থেকে তাকে দেখতে। সে দেরি করবে না এবং সে ভুলে যাবে। আমি জানি, সে ভুলে যাবে। আমি বলেছিলাম, আমার সাথে যা হয়েছে তার জন্য আমি তোমাকে কিছু দিতে চাই না। আমি বলেছি সে দয়া করে নাই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ أَلَا تُحَدِّثِينِي عَنْ مَرَضِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ بَلَى ‏ ‏ثَقُلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَصَلَّى النَّاسُ فَقُلْنَا لَا هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ قَالَ ضَعُوا لِي مَاءً فِي ‏ ‏الْمِخْضَبِ ‏ ‏فَفَعَلْنَا فَاغْتَسَلَ ثُمَّ ذَهَبَ ‏ ‏لِيَنُوءَ ‏ ‏فَأُغْمِيَ عَلَيْهِ ثُمَّ أَفَاقَ فَقَالَ أَصَلَّى النَّاسُ قُلْنَا لَا هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ قَالَ ضَعُوا لِي مَاءً فِي ‏ ‏الْمِخْضَبِ ‏ ‏فَذَهَبَ لِيَنُوءَ فَغُشِيَ عَلَيْهِ قَالَتْ وَالنَّاسُ عُكُوفٌ فِي الْمَسْجِدِ يَنْتَظِرُونَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِصَلَاةِ الْعِشَاءِ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏بِأَنْ يُصَلِّيَ بِالنَّاسِ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَجُلًا رَقِيقًا فَقَالَ يَا ‏ ‏عُمَرُ ‏ ‏صَلِّ بِالنَّاسِ فَقَالَ أَنْتَ أَحَقُّ بِذَلِكَ فَصَلَّى بِهِمْ ‏ ‏أَبُو بَكْرٍ ‏ ‏تِلْكَ الْأَيَّامَ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ خِفَّةً فَخَرَجَ بَيْنَ رَجُلَيْنِ أَحَدُهُمَا ‏ ‏الْعَبَّاسُ ‏ ‏لِصَلَاةِ الظُّهْرِ فَلَمَّا رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏ذَهَبَ لِيَتَأَخَّرَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ أَنْ لَا يَتَأَخَّرَ وَأَمَرَهُمَا فَأَجْلَسَاهُ إِلَى جَنْبِهِ فَجَعَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُصَلِّي قَائِمًا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَاعِدًا ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقُلْتُ أَلَا أَعْرِضُ عَلَيْكَ مَا حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏عَنْ مَرَضِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَاتِ فَحَدَّثْتُهُ ‏ ‏فَمَا أَنْكَرَ مِنْهُ شَيْئًا غَيْرَ أَنَّهُ قَالَ هَلْ سَمَّتْ لَكَ الرَّجُلَ الَّذِي كَانَ مَعَ ‏ ‏الْعَبَّاسِ ‏ ‏قُلْتُ لَا قَالَ هُوَ ‏ ‏عَلِيٌّ ‏ ‏رَحْمَةُ اللَّهِ عَلَيْهِ ‏","","",""],[4895,4895,"","আমি আমার বাবার মৃত্যুর কথা শুনেছি, আমি তার জন্য প্রার্থনা করতে শুনেছি এবং সে বলবে আমি কার সাথে মিলিত হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏سَمِعْتُ ‏ ‏يَحْيَى بْنَ وَثَّابٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4896,4896,"","আমরা বললাম, দুটি জীবনের সেরা দু'টি জীবনের কথা, যা আমি দেখেছি একটি ছেলে যে আমার সাথে বিভ্রান্ত হয়েছে। এই মহিমাটি বলল যে ঈশ্বরের অনুগ্রহে যেন আমি তা দেখি। খোদা জানতো আর ও সার্ভিসে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ جُمْهَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَمْشِي بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقُلْتُ تَمْشِي فَقَالَ إِنْ أَمْشِ فَقَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي وَإِنْ أَسْعَ فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْعَى ‏","","",""],[4897,4897,"","তিনি বলেছিলেন, তুমি তাকে পছন্দ কর আর আমার বাবা তাকে ঘৃণা করবে । ঈশ্বর আপনার স্ত্রীর তালাক দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ تَحْتِي امْرَأَةٌ أُحِبُّهَا وَكَانَ أَبِي يَكْرَهُهَا فَأَمَرَنِي أَنْ أُطَلِّقَهَا فَأَبَيْتُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَأَرْسَلَ إِلَيَّ فَقَالَ يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلِّقْ امْرَأَتَكَ فَطَلَّقْتُهَا ‏","","",""],[4898,4898,"","আমরা রাজার সাথে কথা বলেছি, যখন আমরা বাবার ছেলের সাথে কথা বলেছিলাম, সে স্যর-এর কাছে সত্য বলে স্যরন করেছে এবং তাকে হত্যা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ أَبِي نُعَيْمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ تَعَالَى جَعَلَ الْحَقَّ عَلَى لِسَانِ ‏ ‏عُمَرَ ‏ ‏وَقَلْبِهِ ‏","","",""],[4899,4899,"","আমরা রাজার সাথে আলাপ করছিলাম, কিন্তু আমি বলতে চাচ্ছি আমি একটু বিভ্রান্ত হয়ে গেছি, ঈশ্বর আমাকে কথা বলেছেন কিন্তু তাকে মারতে ব্যর্থ হয়েছে। ফসল অথবা ব্যথা হল সবচেয়ে পবিত্র।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَخْرُجُ نَارٌ قَبْلَ يَوْمِ الْقِيَامَةِ مِنْ بَحْرِ ‏ ‏حَضْرَمَوْتَ ‏ ‏أَوْ مِنْ ‏ ‏حَضْرَمَوْتَ ‏ ‏تَحْشُرُ النَّاسَ قَالُوا فَبِمَ تَأْمُرُنَا يَا رَسُولَ اللَّهِ قَالَ عَلَيْكُمْ ‏ ‏بِالشَّأْمِ ‏","","",""],[4900,4900,"","আমি এত কষ্ট করে বলেছিলাম যে, আমি এত কষ্ট করে বলছি যে, আমি মারা যাওয়ার কথা বলছি । একবার তার কথা বললে আমি তোমাকে একজন ভাল মানুষের কথা দিয়েছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏إِنَّ ‏ ‏أَنَسًا ‏ ‏أَخْبَرَنَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَبَّيْكَ بِعُمْرَةٍ وَحَجٍّ قَالَ ‏ ‏وَهِلَ ‏ ‏أَنَسٌ ‏ ‏خَرَجَ فَلَبَّى بِالْحَجِّ وَلَبَّيْنَا مَعَهُ فَلَمَّا قَدِمَ أَمَرَ مَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏أَنْ يَجْعَلَهَا عُمْرَةً ‏ ‏قَالَ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِأَنَسٍ ‏ ‏فَقَالَ ‏ ‏مَا تَعُدُّونَا إِلَّا صِبْيَانًا ‏","","",""],[4901,4901,"","আমরা এক কিশোর ছেলের কথা বলেছিলাম যে আমাদের ছেলে হবে. আমার বাবা বলেছিলেন লর্ডের লর্ডশিপের লোকেরা তার কাছে প্রার্থনা করবে আর তোমার কাজের জন্য তাকে মার খাওয়া হবে. এমনকি তারা মারা যায়।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضْرَبُونَ إِذَا تَبَايَعُوا طَعَامًا ‏ ‏جُزَافًا ‏ ‏أَنْ يَبِيعُوهُ حَتَّى ‏ ‏يُؤْوُوهُ ‏ ‏إِلَى ‏ ‏رِحَالِهِمْ ‏","","",""],[4902,4902,"","আমরা আনন্দের সাথে বলেছি ঈশ্বর আমাকে ভালো ঈশ্বরের কাছে বলেছেন। তিনি আপনার জন্য প্রভুর অনুগ্রহের জন্য আপনার ছেলের জন্য... ...আপনার কাছে আপনার টাকা দিয়েছেন, যে তার শান্তির জন্য অতিক্রম করেছে এবং তার নিজের স্বপ্ন আছে। পর্যটকরা আমাদের থেকে নয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا ‏","","",""],[4903,4903,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি... ...ঈশ্বর তার জন্য কি করেছেন আর আমি এটা করবো.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِرْكًا ‏ ‏لَهُ فِي مَمْلُوكٍ فَقَدْ عَتَقَ كُلُّهُ فَإِنْ كَانَ لِلَّذِي أَعْتَقَ نَصِيبَهُ مِنْ الْمَالِ مَا يَبْلُغُ ثَمَنَهُ فَعَلَيْهِ عِتْقُهُ كُلُّهُ ‏","","",""],[4904,4904,"","ঈশ্বরের হাত নিয়ে আমরা খুশি হয়েছি... ...ঈশ্বর আমাকে ভালো কথা বলেছেন, তুমি কি এই পথে প্রার্থনা করো না... যন্ত্রণা হচ্ছে, রাতে অথবা মৃগীরোগের মধ্যে পাইলট","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ أَذَّنَ ‏ ‏بِضَجَنَانَ ‏ ‏لَيْلَةً الْعِشَاءَ ثُمَّ قَالَ فِي إِثْرِ ذَلِكَ أَلَا صَلُّوا فِي الرِّحَالِ وَأَخْبَرَنَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْمُرُ مُؤَذِّنًا يَقُولُ ‏ ‏أَلَا صَلُّوا فِي الرِّحَالِ فِي اللَّيْلَةِ الْبَارِدَةِ أَوْ الْمَطِيرَةِ فِي السَّفَرِ ‏","","",""],[4905,4905,"","এরপর তিনি বলেছিলেন যে, আমি যদি প্রার্থনায় থাকি, তা হলে তিনি প্রার্থনা করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَحَتَّهَا ثُمَّ قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَلَا ‏ ‏يَتَنَخَّمْ ‏ ‏فَإِنَّ اللَّهَ تَعَالَى قِبَلَ وَجْهِ أَحَدِكُمْ فِي الصَّلَاةِ ‏","","",""],[4906,4906,"","আমরা ঈশ্বরের হাত দিয়ে কথা বলেছি, তাঁর সাথে কী ঘটেছে, আমি আমার মসজিদে প্রার্থনা করছি, আমি প্রার্থনা করতে পছন্দ করি, কিন্তু স্বাধীনতা খুঁজে না পেয়ে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[4907,4907,"","লর্ডের হ্যান্ডের কথা বলেছিলাম যে একজন যাজক হওয়া বন্ধ করে দিয়েছে, ঈশ্বরের কাছে আপনার আশীর্বাদ আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏تَلَقَّفْتُ ‏ ‏التَّلْبِيَةَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[4908,4908,"","আমি আমার ক্যারিয়ারের কথা বলেছিলাম, যার কাজ করতে হবে আর সে তা করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُوسَى الْجُهَنِيِّ ‏ ‏سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[4909,4909,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, একটা ছেলে আমাকে বলল যে খোদা তার সাথে এমন করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْقَرْعِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[4910,4910,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছিলাম যে এমন একটা ছেলে যে এটা করেছে আর কখনো স্বপ্নই দেখেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[4911,4911,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, ঈশ্বরের একজন সন্তান কিভাবে এটা করেছে আর সেটা করতে হবে, যদি সে তার সাথে যোগাযোগ করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ ‏ ‏بَيِّعَيْنِ ‏ ‏فَأَحَدُهُمَا عَلَى صَاحِبِهِ ‏ ‏بِالْخِيَارِ ‏ ‏حَتَّى يَتَفَرَّقَا أَوْ يَكُونَ ‏ ‏خِيَارًا ‏","","",""],[4912,4912,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি একটি ছেলে সম্পর্কে যে বলেছিল আমি ঈশ্বরের কাছে প্রার্থনা করব। আমি রাতে প্রার্থনা করবো। আমি আপনাকে দুই ফোন করবো, তাই আমি ভয় পাচ্ছি যে আপনি প্রার্থনা করবেন। তাকে তুলে নেওয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ اللَّيْلِ قَالَ ‏ ‏يُصَلِّي أَحَدُكُمْ مَثْنَى مَثْنَى فَإِذَا خَشِيَ أَنْ يُصْبِحَ صَلَّى رَكْعَةً ‏ ‏تُوتِرُ ‏ ‏لَهُ صَلَاتَهُ ‏","","",""],[4913,4913,"","আমরা ঈশ্বরের হাত থেকে একটা ছেলে সম্পর্কে কথা বলেছি যে কিনা ঈশ্বরের শান্তি প্রতিষ্ঠা করেছে, দরজা থেকে কেউ তাদের হত্যা করার জন্য কাউকে হত্যা করতে হবে না। ত্রুজ.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ مِنْ الدَّوَابِّ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى مَنْ قَتَلَهُنَّ فِي قَتْلِهِنَّ وَهُوَ حَرَامٌ الْعَقْرَبُ وَالْفَأْرَةُ وَالْغُرَابُ وَالْحِدَأَةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏","","",""],[4914,4914,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছিলাম, যে ছেলের সাথে শান্তি স্থাপন করেছিল, সে রাগ হারিয়ে ফেলেছিল যখন আমি তার টাকা হারিয়েছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَاتَهُ الْعَصْرُ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[4915,4915,"","ঈশ্বরের হাত আমার কাছে এমন একটা ছেলে আছে যে ঈশ্বরের শান্তিকে পাশ করেছে আর করবে, আমি প্রার্থনা করছি সে তার মঙ্গলের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا نَخْلٍ بِيعَتْ أُصُولُهَا فَثَمَرَتُهَا لِلَّذِي ‏ ‏أَبَّرَهَا ‏ ‏إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏","","",""],[4916,4916,"","আমরা এক সুখী ছেলের কথা বলেছিলাম, যিনি আমাকে ভালো কিছু বলতেন এবং ডিনার যখন তার অনুপস্থিত থাকে এবং বলেন যে ঈশ্বর তাঁর শান্তি নিয়ে এসেছেন এবং তিনি হলেন। ...যাকে তিনি রক্ষা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏كَانَ إِذَا جَدَّ بِهِ السَّيْرُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ بَعْدَمَا يَغِيبُ ‏ ‏الشَّفَقُ ‏ ‏وَيَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا جَدَّ بِهِ السَّيْرُ جَمَعَ بَيْنَهُمَا ‏","","",""],[4917,4917,"","আমরা ঈশ্বরের হাতে কথা বলেছি যে, তার বিবাহ বিচ্ছেদের পরও তার ছেলেকেও তালাক দেয়া হয়েছে। সে ওকে স্পর্শ করবে, সে তার কাছে ফিরে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَفْتَاهُ فَقَالَ ‏ ‏مُرْ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَلْيُرَاجِعْهَا حَتَّى تَطْهُرَ مِنْ حَيْضَتِهَا هَذِهِ ثُمَّ تَحِيضَ حَيْضَةً أُخْرَى فَإِذَا طَهُرَتْ فَلْيُفَارِقْهَا قَبْلَ أَنْ يُجَامِعَهَا أَوْ ‏ ‏لِيُمْسِكْهَا ‏ ‏فَإِنَّهَا الْعِدَّةُ الَّتِي أُمِرَ أَنْ تُطَلَّقَ لَهَا النِّسَاءُ ‏","","",""],[4918,4918,"","আমরা ঈশ্বরের হাত কথা বলেছিলাম যে খোদা হয়ত ঈশ্বরের প্রেম হত, যখন আমরা ভালো বন্ধুর ছেলের সাথে ঝগড়া করতাম, এটা আপনাকে বিরক্ত করতো না আমরা যদি এটা ভয় পাই তাহলে তোমার আর বেলের মধ্যে খুন হবে... ...আর একবার তার কাছে যথেষ্ট হাঙ্গর ছিল, কিন্তু আমি কিভাবে করেছিলাম তারপর সে চলে গেল, ঈশ্বরের অনুগ্রহে ছিল, আর তার পরেও এটা একটা মরুভূমি ছিল, আমার ছেলেকে সমাধান করার জন্য আর আমি হতে পারি। অনেক খুশি এবং তারপর তারা ভেসে ওঠে, এবং তারপর তারা শুধু চলে যায় না.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏وَسَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏كَلَّمَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏حِينَ نَزَلَ ‏ ‏الْحَجَّاجُ ‏ ‏لِقِتَالِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏فَقَالَا لَا يَضُرُّكَ أَنْ لَا تَحُجَّ الْعَامَ فَإِنَّا ‏ ‏نَخْشَى أَنْ يَكُونَ بَيْنَ النَّاسِ قِتَالٌ وَأَنْ يُحَالَ بَيْنَكَ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏قَالَ إِنْ حِيلَ بَيْنِي وَبَيْنَهُ فَعَلْتُ كَمَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ حِينَ حَالَتْ كُفَّارُ ‏ ‏قُرَيْشٍ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ عُمْرَةً فَإِنْ خُلِّيَ سَبِيلِي قَضَيْتُ عُمْرَتِي وَإِنْ حِيلَ بَيْنِي وَبَيْنَهُ فَعَلْتُ كَمَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ ثُمَّ خَرَجَ حَتَّى أَتَى ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏فَلَبَّى بِعُمْرَةٍ ثُمَّ تَلَا ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏ثُمَّ سَارَ حَتَّى إِذَا كَانَ ‏ ‏بِظَهْرِ ‏ ‏الْبَيْدَاءِ ‏ ‏قَالَ مَا أَمْرُهُمَا إِلَّا وَاحِدٌ إِنْ حِيلَ بَيْنِي وَبَيْنَ الْعُمْرَةِ حِيلَ بَيْنِي وَبَيْنَ الْحَجِّ أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ حَجَّةً مَعَ عُمْرَتِي فَانْطَلَقَ حَتَّى ابْتَاعَ ‏ ‏بِقُدَيْدٍ ‏ ‏هَدْيًا ‏ ‏ثُمَّ طَافَ لَهُمَا طَوَافًا وَاحِدًا ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ لَمْ يَزَلْ كَذَلِكَ إِلَى يَوْمِ النَّحْرِ ‏","","",""],[4919,4919,"","আমরা একটা ছেলের কথা বলেছিলাম যে ঈশ্বরের কাছে জন্মগ্রহণ করেছে, আর সে আমাকে বলেছে সে তার কাছে এসেছে। আমরা ঘোড়া আর গোপন জিনিস থেকে কখনো কাপড় পরবো না। সেই কথাগুলো সেই ব্যক্তি সম্বন্ধে কখনোই চিন্তা করবে না ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا نَادَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَلْبَسُ مِنْ الثِّيَابِ إِذَا أَحْرَمْنَا قَالَ ‏ ‏لَا تَلْبَسُوا الْقُمُصَ وَلَا الْعَمَائِمَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا السَّرَاوِيلَاتِ وَلَا الْخُفَّيْنِ إِلَّا أَحَدٌ لَا يَجِدُ نَعْلَيْنِ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً إِلَّا أَنْ يَكُونَ رَجُلٌ لَيْسَ لَهُ نَعْلَانِ فَلْيَقْطَعْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏ ‏وَلَا يَلْبَسْ ثَوْبًا مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏أَوْ ‏ ‏زَعْفَرَانٌ ‏","","",""],[4920,4920,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, তার সাথে কী ঘটেছে, তুমি শুধু মানুষের মঙ্গলের জন্যই চিন্তা করছ, সে তাদের জন্য জিজ্ঞেস করছে আর তারা ভালো আছে তোমার বজ্রপাত আর তোমার সবার মঙ্গলের জন্য বলা হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ فَالْأَمِيرُ الَّذِي عَلَى النَّاسِ رَاعٍ عَلَيْهِمْ وَهُوَ مَسْئُولٌ عَنْهُمْ وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ وَهُوَ مَسْئُولٌ عَنْهُمْ وَالْمَرْأَةُ ‏ ‏رَاعِيَةٌ عَلَى بَيْتِ ‏ ‏بَعْلِهَا ‏ ‏وَوَلَدِهِ وَهِيَ مَسْئُولَةٌ عَنْهُمْ وَعَبْدُ الرَّجُلِ رَاعٍ عَلَى بَيْتِ سَيِّدِهِ وَهُوَ مَسْئُولٌ عَنْهُ أَلَا فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ ‏","","",""],[4921,4921,"","আমরা ঈশ্বরের হাত দিয়ে কথা বলেছি যে, ঈশ্বরের শান্তি নিয়ে করা একটি ছেলে, তারা এটা করতে পারে, তারা তাদের উপর অত্যাচার করে এবং বলে তারা কখনো যেতে দেয় না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الَّذِينَ يَصْنَعُونَ هَذِهِ الصُّوَرَ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ وَيُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[4922,4922,"","আমি যদি আসি তাহলে আমি তোমাকে খুঁজে বের করবো যে দলের ভিক্ষার জন্য তুমি ভিক্ষা চাইবে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4923,4923,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি একটি ছেলে যে এটা করেছে তার কথা যে ঈশ্বর এটা করেছেন তার সাথে, শত শত বছর আগে আমি ফিরে এসেছি","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُسَافَرَ بِالْقُرْآنِ إِلَى أَرْضِ الْعَدُوِّ مَخَافَةَ أَنْ يَنَالَهُ الْعَدُوُّ ‏","","",""],[4924,4924,"","আমরা কথা বলেছিলাম কিভাবে ঈশ্বর আমাকে এমন একটা ছেলের কথা বলেছিলেন যে এটা ঈশ্বরের কাছে চাইতে চেয়েছিল যে কুকুরটা তাকে খেয়ে ফেলেনি অথবা সে প্রতিদিনই তাকে কেটে ফেলে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا إِلَّا كَلْبَ صَيْدٍ ‏ ‏أَوْ مَاشِيَةٍ ‏ ‏نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏","","",""],[4925,4925,"","আমরা ঈশ্বরের হাত সম্পর্কে কথা বলেছি যে আমাকে ঈশ্বরের কাছে প্রার্থনা করতে হয়েছে. সে আমাদের ছেড়ে দিতে বলেছে সে আমাদের যা করতে পারে তাই করতে. আমি একটা বানরকে খুঁজে বের করেছি. আমি তাকে খুঁজে পেয়েছি. আমি তাকে বলেছিলাম যে সে আমাকে বলেছে, আমি তাকে কিছু করতে হবে. আমি তাকে বলতে চাই. আমি তাকে একটা ছেলে হিসেবে বলতে চাই. আমি তাকে বলতে চাই. আমি তাকে বলেছিলাম, আমি তাকে বলেছিলাম, আমি তাকে বলেছিলাম, আমি তোমার কাছে ক্ষমা চাই. আমি এটা করতে চাই. আমি তাকে বলেছিলাম. আমি এটা আমার জন্য ধন্যবাদ দিতে চাই. আমি তাকে বলেছিলাম. আমি তাকে বলেছিলাম. আমি তাকে বলেছিলাম. আমি এটা করতে চাই. আমি তাকে বলেছিলাম. আমি এটা আমার জন্য ধন্যবাদ দিতে হবে. আমি তাকে বলেছিলাম. আমি তাকে বলেছিলাম. আমি তাকে বলেছিলাম. আমি তাকে বলেছিলাম. আমি তাকে বলেছিলাম. ভগবানের উপর দোষ চাপাতে বলবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ تَأْمُرُنَا ‏ ‏نُهِلُّ ‏ ‏قَالَ ‏ ‏يُهِلُّ ‏ ‏أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَأَهْلُ ‏ ‏الشَّأْمِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَأَهْلُ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَيَزْعُمُونَ أَنَّهُ قَالَ وَأَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[4926,4926,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, যে ছেলে ঈশ্বরের দোহাইের উপর ভিত্তি করে এমন এক ছেলের কথা বলছিল যে তাকে লুকিয়ে রেখেছে, ঈশ্বরকে হত্যা করার জন্য ঈশ্বরকে দোষ দিতে পারেনি। যে মহিলা মহিলা বলেছেন, তিনি এক যুবককে বড় করেছেন, তিনি তাকে দেখতে ভয় পেয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَرَّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ يَسَارٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏ذَكَرَتْ النِّسَاءَ فَقَالَ ‏ ‏تُرْخِي شِبْرًا قَالَتْ إِذَنْ تَنْكَشِفَ قَالَ فَذِرَاعًا لَا يَزِدْنَ عَلَيْهِ ‏","","",""],[4927,4927,"","আমরা লর্ডের প্রভুর দিন নিয়ে কথা বলেছি... ...আমি বলেছিলাম যে, আমার ছেলে ঈশ্বরের ইচ্ছা থেকে পালিয়ে এসেছে। বরং চলে যাবার বদলে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏فَرَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَةَ ‏ ‏الْفِطْرِ عَلَى الصَّغِيرِ وَالْكَبِيرِ وَالْحُرِّ وَالْمَمْلُوكِ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ شَعِيرٍ ‏","","",""],[4928,4928,"","আমরা ঈশ্বরের হাত কথা বলেছিলাম এটা কি ভালো হবে যে ঈশ্বর আমাকে বলেছেন যে... ...আমি যা বলেছি তা ছেড়ে দিতে হবে আর তার মাথা ধরে রাখতে হবে তাকে নিচে নামাও।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏ ‏قُلْتُ وَمَا ‏ ‏الْقَزَعُ ‏ ‏قَالَ ‏ ‏أَنْ يُحْلَقَ رَأْسُ الصَّبِيِّ وَيُتْرَكَ بَعْضُهُ ‏","","",""],[4929,4929,"","আমি কথা বলেছি, ঈশ্বর আমাকে কিভাবে ঈশ্বরের শান্তি দিলেন। আমার পেট একটা জির নামে আছে আর তারপর আমি বইগুলো শুকিয়ে ফেলার শপথ নিয়ে যাব। তারপর তারা আমাকে বলল যে আমি কে এসেছি। আমি কি করে বলছি, আমি এটা নিয়ে কথা বলেছি। আমি তাকে জিজ্ঞেস করি, আমি কতটা প্রার্থনা করি ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏هُوَ ‏ ‏وَبِلَالٌ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏فَأَجَافُوا ‏ ‏الْبَابَ وَمَكَثُوا سَاعَةً ثُمَّ خَرَجَ فَلَمَّا فُتِحَ كُنْتُ أَوَّلَ مَنْ دَخَلَ ‏ ‏فَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏بَيْنَ الْعَمُودَيْنِ الْمُقَدَّمَيْنِ وَنَسِيتُ أَنْ أَسْأَلَهُ كَمْ صَلَّى ‏","","",""],[4930,4930,"","আমরা ঈশ্বরের দাসদের কথা বলেছিলাম, যে কিনা তাকে ভালবাসতে বাধ্য ছিল, আমি তাকে ঈশ্বরের অনুগ্রহের জন্য জীবন দিতে হবে, ঈশ্বরের ইচ্ছা ছিল সে করবে এবং আমি চাই সে এটা করবে। আমি চাই, আমি এটা করতে পারি। আমি এটা করতে পারি। এবং আমি যদি চাই, আমি এটা করতে পারি, আমি এটা করতে পারি। এবং আমি যদি আমার ছেলে হয়, আমি আমার বাবা-মা'র কাছে চাই, আমি এটা করতে পারি। আমি যদি আমার বাবা-মা-মা-মা-মা'র কাছে এটা করতে পারি। এবং আমি চাই, আমি তাকে আমার কাছে এটা করতে পারি। আর আমি এটা করতে চাই। আমি যদি আমার ছেলের নাম ব্যবহার করি, আমি আমার কাছে এটা করতে পারি। কিন্তু আমি যদি আমার বাবা না হয়, আমি আমার ছেলের জন্য না করি, আমি এটা করতে পারি। আমি আমার বাবা-মাদারি। আমি চাই, আমি তাকে চাই। আমি এটা করতে হবে। আর আমি এটা করতে চাই, আমি তোমার জন্য একটা ছোটাৎসর জন্য। আর আমি এটা করতে পারি। কিন্তু আমি যদি তুমি আমাকে এটা করতে পারি। আর আমি এটা করতে হবে। ভবিষ্যদ্বাণী তার কাছে প্রার্থনা করে আর তার কথা শুনবে যে সে তাকে অনুসরণ করবে না, আর সে তোমার কৃতকর্মে ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏حَمَلَ عَلَى فَرَسٍ فَأَعْطَاهَا ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَحْمِلَ عَلَيْهَا رَجُلًا فَأُخْبِرَ ‏ ‏عُمَرُ ‏ ‏أَنَّهُ قَدْ وَقَفَهَا يَبِيعُهَا قَالَ فَسَأَلَ عَنْ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْتَاعُهَا ‏ ‏قَالَ ‏ ‏لَا تَبْتَعْهَا وَلَا تَعُدْ فِي ‏ ‏صَدَقَتِكَ ‏","","",""],[4931,4931,"","আমরা ঈশ্বরের ভালোর কথা বলেছি যে তার জন্য প্রার্থনা করেছে, সে দুটো ফিরিয়ে দিয়েছিল এবং আমার বাবার সাথে দেখা করে...","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَمَعَ ‏ ‏عُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏صَدْرًا ‏ ‏مِنْ ‏ ‏إِمَارَتِهِ ‏ ‏ثُمَّ أَتَمَّ ‏","","",""],[4932,4932,"","আমরা একটা সুখী ছেলের কথা বলেছি আর একটা ছেলে আমার সাথে কথা বলেছে, ঈশ্বর, আমি মিথ্যা বলেছি, সে বিশ্বাস করবে যে সে আর কখনো যাবে না। কিন্তু, তার স্ত্রী তাকে তার সঙ্গে দেখা করতে বলে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أَصَبْتُ ‏ ‏أَرْضًا ‏ ‏بِخَيْبَرَ ‏ ‏لَمْ ‏ ‏أُصِبْ ‏ ‏شَيْئًا قَطُّ هُوَ أَنْفَسَ عِنْدِي مِنْهُ فَقَالَ إِنْ شِئْتَ ‏ ‏حَبَسْتَ ‏ ‏أَصْلَهَا وَتَصَدَّقْتَ بِهَا قَالَ فَتَصَدَّقَ بِهَا لَا يُبَاعُ أَصْلُهَا وَلَا تُوهَبُ وَلَا تُورَثُ قَالَ ‏ ‏فَتَصَدَّقَ بِهَا فِي الْفُقَرَاءِ وَالضَّيْفِ وَالرِّقَابِ وَفِي السَّبِيلِ وَابْنِ السَّبِيلِ لَا جُنَاحَ عَلَى مَنْ ‏ ‏وَلِيَهَا ‏ ‏أَنْ يَأْكُلَ ‏ ‏بِالْمَعْرُوفِ ‏ ‏أَوْ يُطْعِمَ صَدِيقًا غَيْرَ ‏ ‏مُتَمَوِّلٍ ‏ ‏فِيهِ ‏","","",""],[4933,4933,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, আমাদের সাথে ঈশ্বরের একটা ছেলের কথা, যিনি আমাদের এই কাজ করেছেন। আমরা দুজন যারা ভালো বিশ্বাস করে বেঁচে আছি এবং শান্তিতে আছে তাদের কাছে আমরা অনুপ্রাণিত হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَعَثَنَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏بَلَغَتْ سُهْمَانُنَا اثْنَيْ عَشَرَ بَعِيرًا ‏ ‏وَنَفَّلَنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا بَعِيرًا ‏","","",""],[4934,4934,"","আমরা ঈশ্বরের হাত দিয়ে কথা বলেছিলাম যে, ঈশ্বরের দোহাই দিয়ে একটা ছেলেকে বলা যে... ...যে কিনা...","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبَّقَ ‏ ‏بَيْنَ الْخَيْلِ ‏ ‏الْمُضَمَّرَةِ ‏ ‏مِنْ ‏ ‏الْحَفْيَاءِ ‏ ‏إِلَى ‏ ‏ثَنِيَّةِ الْوَدَاعِ ‏ ‏وَمَا لَمْ ‏ ‏يُضَمَّرْ ‏ ‏مِنْهَا مِنْ ‏ ‏ثَنِيَّةِ الْوَدَاعِ ‏ ‏إِلَى مَسْجِدِ ‏ ‏بَنِي زُرَيْقٍ ‏","","",""],[4935,4935,"","আমরা ঈশ্বরের একজন সুখী পুত্রের কথা বলেছি, ঈশ্বরের কাছে বিখ্যাতদের সমর্পণ করতে হবে এবং আপনার আত্মার কথা মনে রাখতে হবে। ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং তিনি তার নারীকে আত্মসমর্পণ করবেন। ৯-এ যাওয়ার জন্য, এবং জীবনের সেরাটা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الشَّهْرُ تِسْعٌ وَعِشْرُونَ فَذَكَرُوا ذَلِكَ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَتْ يَرْحَمُ اللَّهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏وَهَلْ هَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا فَنَزَلَ لِتِسْعٍ وَعِشْرِينَ فَقِيلَ لَهُ فَقَالَ ‏ ‏إِنَّ الشَّهْرَ قَدْ يَكُونُ تِسْعًا وَعِشْرِينَ ‏","","",""],[4936,4936,"","আমরা আনন্দের সাথে কথা বলেছি, আমার ছেলের স্বপ্ন বহন করার জন্য আপনার টাকা নিয়ে এসেছি। সে তার ভাইয়ের কাছে এই কথা বলে যে ঈশ্বর তাকে নিরাপদে ফোন করে নিরাপদে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانَ يَعِظُ أَخَاهُ فِي الْحَيَاءِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُ فَإِنَّ ‏ ‏الْحَيَاءَ مِنْ الْإِيمَانِ ‏","","",""],[4937,4937,"","আমরা আমার ছেলের কথা বলেছিলাম, আমার ছেলের জন্য ভালো ছেলের জন্য, যে কিনা ঈশ্বরের দোহাইর জন্য জন্ম দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَتَبَايَعُوا الثَّمَرَ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[4938,4938,"","দুজন নেতা, দুজন নেতা তার ফিরে আসার আগে কী করা উচিত, তা বলার রীতি পালন করেছে । ঈশ্বর এমনকি তাদের জীবনকে কখনোই বৃদ্ধি করতে পারতেন না ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ حَفْصٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي سَفَرٍ فَصَلَّى الظُّهْرَ وَالْعَصْرَ رَكْعَتَيْنِ رَكْعَتَيْنِ ثُمَّ قَامَ إِلَى ‏ ‏طِنْفِسَةٍ ‏ ‏فَرَأَى نَاسًا يُسَبِّحُونَ بَعْدَهَا فَقَالَ مَا يَصْنَعُ هَؤُلَاءِ قُلْتُ يُسَبِّحُونَ قَالَ لَوْ كُنْتُ مُصَلِّيًا قَبْلَهَا أَوْ بَعْدَهَا لَأَتْمَمْتُهَا صَحِبْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى قُبِضَ فَكَانَ ‏ ‏لَا يَزِيدُ عَلَى رَكْعَتَيْنِ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَتَّى قُبِضَ فَكَانَ لَا يَزِيدُ عَلَيْهِمَا ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَذَلِكَ ‏","","",""],[4939,4939,"","বাবার ছেলের কথা বলেছিলাম আমার সাথে বিয়ের স্বপ্নের কথা। সে সূর্যাস্ত আর বাসার মধ্যে একত্র হলো... ...যা কখনোই হয়নি। তাদের একটা প্রভাব থাকতে অনুমতি দেওয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِجَمْعٍ ‏ ‏بِإِقَامَةٍ وَلَمْ يُسَبِّحْ بَيْنَهُمَا وَلَا عَلَى أَثَرِ وَاحِدَةٍ مِنْهُمَا ‏","","",""],[4940,4940,"","আমরা একটি ছেলে যে শয়তানী অত্যাচারীর কথা শুনে খুশি যে, তার প্রতি ঘৃণা প্রকাশ করার জন্য, আল্লাহ আমাদের বলেছেন যে সে যে অত্যাচার করেছে তার উপর ছেড়ে দিতে হবে এবং সে বলল যে, তার কাছ থেকে আমার শুনতে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏سُئِلَ عَنْ نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ نَعَمْ ‏ ‏و قَالَ ‏ ‏طَاوُسٌ ‏ ‏وَاللَّهِ إِنِّي سَمِعْتُهُ مِنْهُ ‏","","",""],[4941,4941,"","আমরা দুই গ্রীষ্মের কথা বলেছি যা ঈশ্বরের সাথে আমার দেখা হয়েছিল, আমি এক ছেলের কথা শুনেছি যে কিনা ঈশ্বরের প্রতি ভালবাসা দেখিয়েছে। সে বলল যে, সে ভাড়া পেয়েছে নাকি সে এখন একটা ফ্রাইর ভেতর পড়ে আছে। তাকে ভালোর খোঁজে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏أَوْ ثَوْبَهُ شَكَّ ‏ ‏يَحْيَى ‏ ‏مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4942,4942,"","আমরা দুটো জাহাজের কথা বলেছিলাম, যখন আল্লাহ্ একটা ছেলে শুনেছেন যে সে কখনো ঈশ্বরের কাছে প্রার্থনা করবে না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُمَا تَوَجَّهَتْ بِهِ ‏","","",""],[4943,4943,"","ঈশ্বর আমাদের বলেন যে, রাতের বেলা তিনি তার মন প্রতারণা করার ও উজ্জ্বল করার আদেশ দেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تُصِيبُنِي الْجَنَابَةُ مِنْ اللَّيْلِ فَأَمَرَهُ أَنْ ‏ ‏يَغْسِلَ ذَكَرَهُ وَلْيَتَوَضَّأْ ‏","","",""],[4944,4944,"","আমরা আবেগ নিয়ে খেলা এবং একটি হিংস্র মন নিয়ে কথা বলেছি যা আমাদের জন্য একটা রীতি তৈরি করেছে যা আমার সাথে ঘটেছে। আমি একটি ছেলের কথা বলেছি, যা আমাকে বলা হয়েছে যে তিনি যা করেছেন এবং তিনি যা করেছেন তা করেছেন। আপনার ভাষার জন্য, তিনি বলেন যে প্রেম এবং প্রতিবেশী হলো আসল নকল এবং রক্ত। এই আলো সব সত্য এবং এটাই কল্পনা। আমি ক্লান্ত আর আমার মিউজিকের পোষাক পড়ার আদেশ আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏عَنْ ‏ ‏زَاذَانَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَخْبِرْنِي مَا نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْأَوْعِيَةِ وَفَسِّرْهُ لَنَا بِلُغَتِنَا فَإِنَّ لَنَا لُغَةً سِوَى لُغَتِكُمْ قَالَ ‏ ‏نَهَى عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَهُوَ ‏ ‏الْجَرُّ ‏ ‏وَنَهَى عَنْ ‏ ‏الْمُزَفَّتِ ‏ ‏وَهُوَ ‏ ‏الْمُقَيَّرُ ‏ ‏وَنَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَهُوَ الْقَرْعُ وَنَهَى عَنْ ‏ ‏النَّقِيرِ ‏ ‏وَهِيَ النَّخْلَةُ تُنْقَرُ نَقْرًا وَتُنْسَجُ نَسْجًا قَالَ فَفِيمَ تَأْمُرُنَا أَنْ نَشْرَبَ فِيهِ قَالَ الْأَسْقِيَةُ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَأَمَرَ أَنْ ‏ ‏نَنْبِذَ ‏ ‏فِي الْأَسْقِيَةِ ‏","","",""],[4945,4945,"","আমরা দুই গ্রীষ্মের কথা বলেছি একটা কোদাল পুত্র একটা চাঁদের ছেলের কথা শুনে যে ঈশ্বরের জন্য প্রার্থনা করেছিল। ভিলেন.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنْصَبُ ‏ ‏لِلْغَادِرِ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ يُقَالُ هَذِهِ غَدْرَةُ فُلَانٍ ‏","","",""],[4946,4946,"","আমরা দুজন জাহাজের কথা বলেছিলাম, একটা গোরস্থানের ছেলের সঙ্গে কথা বলেছিলাম, যিনি বলেছিলেন যে তিনি মারা গিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَ الْمُحْرِمُ ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏زَعْفَرَانٌ ‏ ‏أَوْ ‏ ‏وَرْسٌ ‏","","",""],[4947,4947,"","আমরা কথা বলছিলাম যে একটা ছেলে কাজ করছে আর বলে যে সে আর কখনো যেতে পারবে না। আমি নিশ্চিত নই সে তোমাকে থামাতে চাচ্ছে না যে আমরা কি করছি। অন্ধকার থেকে মানুষ বন্ধ করতে চাই আমি তোমাকে বলতে চাই যে, ছেলেকে তার প্রার্থনার উত্তর দিতে এবং তাকে নামিয়ে দিতে বলা হয়েছে। আর পবিত্র এবং ঈশ্বরের বছর তুমি। এটা ধরে নাও যে আমি আসলেই একটা বাচ্চা মেয়ের কাছ থেকে খুব একটা কাজ করি যে শিকারী ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏أَخْبَرَنِي ‏ ‏وَبَرَةُ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ أَيَصْلُحُ أَنْ أَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏وَأَنَا مُحْرِمٌ قَالَ مَا يَمْنَعُكَ مِنْ ذَلِكَ قَالَ إِنَّ فُلَانًا ‏ ‏يَنْهَانَا عَنْ ذَلِكَ حَتَّى يَرْجِعَ النَّاسُ مِنْ الْمَوْقِفِ وَرَأَيْتُهُ كَأَنَّهُ مَالَتْ بِهِ الدُّنْيَا وَأَنْتَ ‏ ‏أَعْجَبُ ‏ ‏إِلَيْنَا مِنْهُ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَجَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَسَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَسُنَّةُ اللَّهِ تَعَالَى ‏ ‏وَرَسُولِهِ أَحَقُّ أَنْ تُتَّبَعَ مِنْ سُنَّةِ ابْنِ فُلَانٍ إِنْ كُنْتَ صَادِقًا ‏","","",""],[4948,4948,"","আমরা ঈশ্বরের হাত ভালোর কথা বলেছি যে ঈশ্বর তার শান্তি রক্ষা করেছেন বলে যে, তারা সবাই পান করে, যতক্ষণ না তারা আপনার মায়ের ছেলেকে রক্ষা করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[4949,4949,"","ঈশ্বরের হাতের কথা বলেছিলাম, ঈশ্বরের হাতে ভালো কিছু করার জন্য, তার ঈর্ষার কারণে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُحْتَلَبَ الْمَوَاشِي مِنْ غَيْرِ إِذْنِ أَهْلِهَا ‏","","",""],[4950,4950,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি একটি ছেলের জন্য, যে কিনা কখনো ঈশ্বরের স্বপ্ন দেখেনি। আমি সুপারিশ করছি, আমি কিছু লেখা নেই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ لَهُ شَيْءٌ ‏ ‏يُوصِي فِيهِ يَبِيتُ لَيْلَتَيْنِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[4951,4951,"","তিনি বলেছিলেন যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছিলেন এবং তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ أَصَابَ ‏ ‏ابْنَ عُمَرَ ‏ ‏الْبَرْدُ وَهُوَ مُحْرِمٌ فَأَلْقَيْتُ عَلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏بُرْنُسًا ‏ ‏فَقَالَ أَبْعِدْهُ عَنِّي أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْبُرْنُسِ ‏ ‏لِلْمُحْرِمِ ‏","","",""],[4952,4952,"","আমরা ঈশ্বরের জন্য ভাল ছেলের খেলা নিয়ে কথা বলেছিলাম, যার কাছে ঈশ্বরের শান্তি ছিল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏مَسْجِدَ قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[4953,4953,"","ঈশ্বরের হাত নিয়ে কথা বলেছি, ঈশ্বরের শান্তি নিয়ে করা একটি ছেলের কথা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[4954,4954,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি যে ছেলে কখনো তোমাকে কোথাও খুন করতে দেয় নি। আমি দেখেছি ঈশ্বর তাকে জানতেন এবং তাকে সঠিক এবং সঠিক হতে শেখানো হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَا أَتْرُكُ اسْتِلَامَهُمَا فِي شِدَّةٍ وَلَا رَخَاءٍ بَعْدَ إِذْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا الرُّكْنَ ‏ ‏الْيَمَانِيَ وَالْحَجَرَ ‏","","",""],[4955,4955,"","আমরা ঈশ্বরের হাত নিয়ে কথা বলেছি, তিনি আমার সাথে একটি ছেলের সাথে কথা বলেছিলেন যে তার শান্তির জন্য ঈশ্বরের কাছে পাঠানো হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَاعَنَ بَيْنَ رَجُلٍ وَامْرَأَتِهِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَفَرَّقَ بَيْنَهُمَا ‏","","",""],[4956,4956,"","আমরা বলেছিলাম, ঈশ্বর আমাকে কিভাবে একটা ছেলে সম্পর্কে বলেছিলেন যে তার মৃত্যুর পর, যখন আমরা অবতরণ করলাম, আমরা ঈশ্বরের দোহাই চেয়ে প্রার্থনা করলাম এবং আল্লাহ তাকে এটা বলতে বললেন। ( মথি ৬: ৩৩) তিনি তাঁর আদর্শগুলো উল্লেখ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏يَوْمُ عَاشُورَاءَ ‏ ‏يَوْمًا يَصُومُهُ أَهْلُ الْجَاهِلِيَّةِ فَلَمَّا نَزَلَ رَمَضَانُ سُئِلَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هُوَ يَوْمٌ مِنْ أَيَّامِ اللَّهِ تَعَالَى مَنْ شَاءَ صَامَهُ وَمَنْ شَاءَ تَرَكَهُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْأَخْنَسِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[4957,4957,"","আমরা কথা বলেছি, একটি সুখী ছেলের সাথে লড়াই করে আপনার বিষ নিয়ে লড়াই করার মাধ্যমে... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি ভুল পথে বিশ্বাসের জন্য ঈশ্বরের লড়াইকে মেনে নিতে চান না কোন কাঁটাহীন টাক।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْبَلُ اللَّهُ تَعَالَى ‏ ‏صَدَقَةً ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏ ‏وَلَا صَلَاةً بِغَيْرِ طُهُورٍ ‏","","",""],[4958,4958,"","আমরা অনেক বছর ধরে বেনকে সাহায্য করেছি, ঈশ্বর আদেশ দিয়েছেন তাকে সাহায্য করতে আর তার অন্তরের জন্য প্রার্থনা করতে হবে... আমার বাবা ভালবাসাকে ভালোবাসে, বেনকে বৃদ্ধ বয়সে এবং এক স্বপ্ন থেকে দুরে থাকতে সাহায্য করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى حِمَارٍ وَهُوَ مُتَوَجِّهٌ إِلَى ‏ ‏خَيْبَرَ ‏ ‏نَحْوَ الْمَشْرِقِ ‏ ‏وَقَرَأْتُهُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنِ ‏ ‏أَبِي الْحُبَابِ سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَلَمْ يَقُلْ نَحْوَ الْمَشْرِقِ ‏","","",""],[4959,4959,"","আমরা ইতোমধ্যে আপনার টাকা করেছি যারা আমাকে বলেছে আমি কত বছর সুখী হয়েছি. ঈশ্বরের অনুগ্রহ তার কাছে তার অনুগ্রহের জন্য প্রার্থনা করা হয়েছে এবং তার কাছে পাঠ করুন: আমার বাবা একটি ছেলের সাথে বড় হয়েছেন কে ঈশ্বরের করুণা পেতে পারে?","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏ابْنُ عُمَرَ ‏ ‏أَمَا لَكَ بِرَسُولِ اللَّهِ أُسْوَةٌ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏عَلَى بَعِيرِهِ ‏ ‏وَقَرَأْتُهُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[4960,4960,"","আমরা অনেক বছর ধরে আমার বাবার অনুসন্ধানের কথা বলেছি যে ছেলে প্রমাণ করেছে, আল্লাহ্‌ আছে এবং তার সাথে আছে যারা তার কাছে প্রার্থনা করতে এসেছে","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَاءَ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[4961,4961,"","আমরা একে অপরের সাথে কথা বলেছি... ...যে ছেলে ঈশ্বরের সাথে কথা বলেছে... ...সে তার কাছে এসেছে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ الْجُمَحِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَأْذَنَكُمْ نِسَاؤُكُمْ إِلَى الْمَسَاجِدِ فَأْذَنُوا لَهُنَّ ‏","","",""],[4962,4962,"","আমরা একটা ছেলের কথা বলেছি যে আমার বাবার সাথে বড় হয়ে নরকে গিয়েছে, যে তার বাবার সাথে একটু পেরে গেছে। সে তার বাবার সামনে কখনো ফোন করেনি, পরে সে বলেছিল যে ঈশ্বর আছে ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ عَبْدِ اللَّهِ الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏خَرَجَ يَوْمَ عِيدٍ فَلَمْ يُصَلِّ قَبْلَهَا وَلَا بَعْدَهَا فَذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَهُ ‏","","",""],[4963,4963,"","আমরা অনেকবার বলেছি, আমার বাবার অমর পুত্র, বাবার সবচেয়ে ভালো কথা বলেছে যে আমার একটা ছেলে আছে যে অন্ধকারে আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي حَنْظَلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ رَكْعَتَانِ سُنَّةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4964,4964,"","আমরা একজন কবির কথা বলেছি যে ভগবানের কাছে প্রার্থনা করেছে, সে তার আদেশের ছেলে, হাঁটু গেড়ে প্রার্থনা করছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏صَدْرًا ‏ ‏مِنْ ‏ ‏إِمَارَتِهِ ‏ ‏صَلَّوْا ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ ‏","","",""],[4965,4965,"","আমরা আমার বাবার গোপন কথা বলছি... ...তার বাবাকে ঈশ্বরের কাছে খুঁজতে... ...সে দুটো জায়গায় পড়ে যাবে... ধুলো কিছুটা কঠিন, ক্যাভররা বলে এটা ভগবান আমি সাহস করি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ وَالرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ بِضْعًا وَعِشْرِينَ مَرَّةً ‏ ‏أَوْ بِضْعَ عَشْرَةَ مَرَّةً ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[4966,4966,"","আমরা অনেক বছর ধরে কথা বলেছি একজন দেবীর ছেলে খুঁজে পেতে পারে এমন একজন দেবীর ছেলে খুঁজে পেতে। প্রভু ও প্রভু","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏الْوَتْرِ ‏ ‏أَوَاجِبٌ هُوَ فَقَالَ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُسْلِمُونَ ‏","","",""],[4967,4967,"","আমরা দুই বছর ধরে আমার বোন হিসেবে জন্ম নেয়া আমার বোন হওয়ার কথা বলেছি। লর্ড প্রার্থনা করলেন এবং প্রার্থনা করলেন রাতের বেলা প্রার্থনার জন্য তাকে প্রার্থনা করতে। আমি তোমার মত প্রভু দেবী, তুমি যদি সকাল প্রতারণা করো বা কোনায় ঠক ফেলে দাও, তাহলে সে কামা দিয়ে চলে আসবে, তারপর সে তার কাছে আসবে ঘোমটার কুমার সাথে। দুই বার বলতে, তুমি সকালে ভয় পাও।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ حُدَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ صَلَاةِ اللَّيْلِ وَأَنَا بَيْنَ السَّائِلِ وَبَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ ‏ ‏فَأَوْتِرْ ‏ ‏بِرَكْعَةٍ قَالَ ثُمَّ جَاءَ عِنْدَ ‏ ‏قَرْنِ ‏ ‏الْحَوْلِ ‏ ‏وَأَنَا بِذَاكَ الْمَنْزِلِ بَيْنَهُ وَبَيْنَ السَّائِلِ فَسَأَلَهُ فَقَالَ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ ‏ ‏فَأَوْتِرْ ‏ ‏بِرَكْعَةٍ ‏","","",""],[4968,4968,"","আমরা একে অপরের জীবন এবং দুই বছর ধরে ভাল খেলেছি, ঈশ্বর আদেশ দিয়েছেন তাকে আসতে এবং আত্মসমর্পণ করতে হবে তিনি বলেন তিনি একটি মারাত্মক ওয়ার্ড খুঁজে পেতে পারেন. ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْتِي ‏ ‏قُبَاءَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مَسْجِدَ قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[4969,4969,"","আমরা আমার ছেলের জন্য কথা বলেছি বাবার ছেলের চেয়ে বেশি কিছু হতে। সে তার জন্য প্রার্থনা করতে বলেছিল আর আমাকে সিল্কের শ্রেণীতে আত্মসমর্পণ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏فِئَةُ ‏ ‏الْمُسْلِمِينَ ‏","","",""],[4970,4970,"","আমরা দু'বছর আগে একে অপরের সাথে কথা বলেছি এবং প্রভু একটি ছেলের জন্য দুটি জীবন দিয়েছেন, যে তার পাস হয়েছে। ঈশ্বরের দয়া তাকে আদেশ দিয়েছেন এবং তার প্রভুর কাছে আত্মসমর্পণ করতে হবে। আপনার কাজ","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏إِذَا لَقُوكُمْ قَالُوا ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَقُولُوا وَعَلَيْكُمْ ‏","","",""],[4971,4971,"","আমরা একে অপরের জীবনের কথা বলছি, তিনি বলেছেন আমি পঞ্চমবারের ছেলে। আমার ভাই বলেছে, আমার বাবা তাকে এমন একটা ছেলে বানিয়েছে যে চোরদের মাধ্যমে পার হয়ে গেছে। মুক্ত হওয়ার অধিকার, সে বলেছে সে তোমার সঙ্গী।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي حَلْقَةٍ فَسَمِعَ رَجُلًا فِي حَلْقَةٍ أُخْرَى وَهُوَ يَقُولُ لَا وَأَبِي فَرَمَاهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏بِالْحَصَى وَقَالَ إِنَّهَا كَانَتْ يَمِينَ ‏ ‏عُمَرَ ‏ ‏فَنَهَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهَا وَقَالَ إِنَّهَا شِرْكٌ ‏","","",""],[4972,4972,"","আমরা অনেক বছর ধরে আমার বাবার অনুসন্ধান করেছি, যে ছেলে তার উপর পাশ করেছে, তার জন্য ঈশ্বরকে দু'টি চিনি দিতে হয়েছে, তাকে মার খেতে হয়েছে, আর বলতেছি যে তোমার পানীয় কি পান করেছে ...অহংবোধ, সকাল থেকে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النَّجْرَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَكْرَانَ فَضَرَبَهُ ‏ ‏الْحَدَّ ‏ ‏ثُمَّ قَالَ مَا شَرَابُكَ فَقَالَ زَبِيبٌ وَتَمْرٌ فَقَالَ ‏ ‏لَا تَخْلِطْهُمَا يَكْفِي كُلُّ وَاحِدٍ مِنْهُمَا مِنْ صَاحِبِهِ ‏","","",""],[4973,4973,"","আমরা একটি ছেলে কথা বলেছি যে তার কাছে একটা ছেলে আছে তার দয়া করে বলে, সে ডাক্তার আর সুরের জন্য হাত পেয়েছে আর নকল দুনিয়া বলেছে সে একটু ক্লান্ত হয়ে যাবে এক।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَارِبِ بْنِ دِثَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأُرَاهُ قَالَ ‏ ‏وَالنَّقِيرِ ‏","","",""],[4974,4974,"","আমরা দু'বছর আগে একে অপরের সাথে কথা বলেছি এবং প্রভু এক ছেলের জন্য দুটি জীবন অতিবাহিত করেছেন, যার জন্য সে পাশ করেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার জন্য প্রার্থনা করেছেন, আপনি সেখানে যাননি। তোমাকে ঠিক করতে তোমার আর কোন প্রয়োজন নেই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُوا عَلَى هَؤُلَاءِ الْقَوْمِ الْمُعَذَّبِينَ أَصْحَابِ ‏ ‏الْحِجْرِ ‏ ‏إِلَّا أَنْ تَكُونُوا بَاكِينَ فَإِنْ لَمْ تَكُونُوا بَاكِينَ فَلَا تَدْخُلُوا عَلَيْهِمْ أَنْ يُصِيبَكُمْ مَا أَصَابَهُمْ ‏","","",""],[4975,4975,"","আমরা দুই মাস ঈশ্বরের অনুগ্রহের কথা বলেছি, সে বোকা পাঁচ বছর বয়সীদের উদ্ধার করেছে যারা তাকে সাহায্য করতে পারেনি কিন্তু ঈশ্বরের কাছে বিশ্ব বিজ্ঞান আছে। আর তুমি কি জানো তুমি কি করছ? কাল বৃষ্টিতে, যা করতে যাচ্ছ তা হারাচ্ছো... ...আর তুমি ঈশ্বরের মরণ হারাচ্ছো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَفَاتِيحُ الْغَيْبِ خَمْسٌ لَا يَعْلَمُهَا إِلَّا اللَّهُ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏}","","",""],[4976,4976,"","আমরা কয়েক বার কথা বলেছি আর আমরা বলেছিলাম যে আমাদের থামাতে চেষ্টা করা বন্ধ করা বন্ধ করা। \"যে তোমাকে দুর্বলতা থেকে তৈরি করেছিল এবং তারপর সেটা আপনার অন্ধকার নিঃশ্বাস থেকে বের করে দিল তারপর সে কিছু শক্তিশালী দুর্বলতার মধ্য থেকে বের করে... ...আর তারপর অন্ধকার শক্তি দিয়ে তৈরি, আর সে বলল যে সে একজন যাজক. তোমাকে নিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏فُضَيْلٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏فُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏ابْنِ عُمَرَ ‏ { ‏الَّذِي خَلَقَكُمْ مِنْ ضَعْفٍ ثُمَّ جَعَلَ مِنْ بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنْ بَعْدِ قُوَّةٍ ضَعْفًا ‏} ‏فَقَالَ ‏ { ‏اللَّهُ الَّذِي خَلَقَكُمْ ‏ ‏مِنْ ضُعْفٍ ‏ ‏ثُمَّ جَعَلَ مِنْ بَعْدِ ضُعْفٍ قُوَّةً ثُمَّ جَعَلَ مِنْ بَعْدِ قُوَّةٍ ضُعْفًا ‏} ‏ثُمَّ قَالَ ‏ ‏قَرَأْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا قَرَأْتَ عَلَيَّ فَأَخَذَ عَلَيَّ كَمَا أَخَذْتُ عَلَيْكَ ‏","","",""],[4977,4977,"","আমরা ইতিমধ্যে একটি বাপ্তিস্মের বিষয়ে কথা বলেছি, ঈশ্বরের অনুগ্রহে তিনি এলাকার নারীদের দ্বারা বিবাহবিচ্ছেদ করেছেন এবং তিনি বলেছেন তিনি ঈশ্বরের কাছে জন্মগ্রহণ করেছেন, তিনি তাকে দিতে হয়েছে তার কথা, এটা তালাক, আর এটা রান্না বা ভাল্লুক।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى آلِ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ فِي الْحَيْضِ فَذَكَرَ ذَلِكَ ‏ ‏عُمَرُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ لِيُطَلِّقْهَا وَهِيَ ‏ ‏طَاهِرٌ أَوْ حَامِلٌ ‏","","",""],[4978,4978,"","আমরা দুইটা জীবন করেছি যেহেতু এই চমক আমাদের ঈশ্বরের দিনের রাজধানী সম্পর্কে বলেছে, তার উপর প্রভু যে দায়িত্ব দিয়েছেন তার উপর... ব্যর্থ হচ্ছি না, তোমার ফোন কখনো ভুলতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏اسْتَأْذَنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعُمْرَةِ ‏ ‏فَأَذِنَ لَهُ فَقَالَ يَا أَخِي أَشْرِكْنَا فِي صَالِحِ دُعَائِكَ وَلَا تَنْسَنَا ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏مَا أُحِبُّ أَنَّ لِي بِهَا مَا طَلَعَتْ عَلَيْهِ الشَّمْسُ ‏","","",""],[4979,4979,"","আমরা আমাদের কিছু আমেরিকান ছেলে সম্পর্কে কথা বলেছি, যে বলেছে, ভবিষ্যদ্বাণী তাকে কথা বলতে বাধ্য করেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏مَكَّةَ ‏ ‏نَهَارًا ‏","","",""],[4980,4980,"","আমরা একজন কবির কথা বলেছি যে স্বপ্নের জন্ম দিয়েছে, আর দ্বিতীয় জন উপরে যায়।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدْخُلُ مِنْ ‏ ‏الثَّنِيَّةِ الْعُلْيَا ‏ ‏وَيَخْرُجُ مِنْ ‏ ‏السُّفْلَى ‏","","",""],[4981,4981,"","আমরা দুজন জাহাজের কথা বলেছি, যে কিনা আগে কখনো কোন মানুষের কথা শুনিনি। অথবা যদি তাদের মধ্যে কেউ বলে যে ঈশ্বর তাকে উদ্ধার করেছেন এবং তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন। আর আল ্ লাহ ্ ‌ র প ্ রতি -- স ্ মরণ করো ! তিনি তাঁর প ্ রভুকে আহ ্ বান করতে থাকো , আর তাঁর প ্ রভুকে ভয়-ভক ্ তি করো , আর তাঁর দিকে পরিচালিত করো , প্রভু, লর্ড, প্রভুর কাছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏سَمِعَهُ مِنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَقْبَلَ ‏ ‏رَجُلَانِ ‏ ‏مِنْ الْمَشْرِقِ فَتَكَلَّمَا ‏ ‏أَوْ تَكَلَّمَ أَحَدُهُمَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا ‏ ‏أَوْ إِنَّ ‏ ‏الْبَيَانَ ‏ ‏سِحْرٌ ‏","","",""],[4982,4982,"","আমরা বাবার বেঁচে যাওয়া ভাইয়ের ব্যাপারে একটা নিয়ম সম্পর্কে কথা বলেছি যে বলেছে সে চোর। ঈশ্বরের কাছে আত্মসমর্পণ করতে হবে যদি তুমি তাদের কবরে গিয়ে তাকে ছেড়ে দাও। ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِىِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وَضَعْتُمْ مَوْتَاكُمْ فِي قُبُورِهِمْ فَقُولُوا بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4983,4983,"","আমরা একে অপরের সাথে কথা বলেছি, কিন্তু আমরা একটা ছেলে যে কিনা ঈশ্বরের কাজে বাধা দিয়েছে, সেই ছেলে যে কিনা শহর থেকে পালিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلُ بْنُ غَزْوَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُعْرَضُ عَلَى ابْنِ ‏ ‏آدَمَ ‏ ‏مَقْعَدُهُ مِنْ الْجَنَّةِ وَالنَّارِ ‏ ‏غُدْوَةً ‏ ‏وَعَشِيَّةً فِي قَبْرِهِ ‏","","",""],[4984,4984,"","আমরা একে অপরের কথা বলেছি এবং সবচেয়ে ভালোর কথা বলেছি যে ঈশ্বর আছে আর তিনি মানুষের কাছে তা বিক্রি করেছেন যারা এটা দিয়ে তাকে চুমু দিতে চেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى يَقْبِضَهُ ‏","","",""],[4985,4985,"","আমার বাবার গোপন কথা বলছি... ...আমার প্রভু ঈশ্বরের পুত্রের উপর আমার বাবার বিশ্বাস নিয়ে... ...তিনি নবী নবীকে তার প্রার্থনা করার কথা দিয়েছিলেন এবং তিনি তার কেটে ফেলার আগেই তিনি তার কাছে আসবেন। তার টাকা দিয়ে তার অক্সিজেন বিক্রি শেষ করতে হবে যদিও সে হয়তো তার মুখে থাকতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏النَّجْرَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَجُلَيْنِ تَبَايَعَا عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَخْلًا قَبْلَ أَنْ تَطْلُعَ الثَّمَرَةُ فَلَمْ تُطْلِعْ شَيْئًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى أَيِّ شَيْءٍ تَأْكُلُ مَالَهُ ‏ ‏وَنَهَى عَنْ بَيْعِ الثَّمَرِ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[4986,4986,"","আমরা ইতিমধ্যে আপনার বিষ সম্পর্কে কথা বলেছি একটি ছেলের নামে একটি ছেলে নিহত করা ছেলে যে ছেলে ছেলে হয়েছে তার নামে। ঈশ্বর বলেন যে, তিনি অন্য জনের কাছে যাবেন এবং তিনি যাবেন । একই জায়গায় যাবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا اشْتَرَيْتَ الذَّهَبَ بِالْفِضَّةِ أَوْ أَحَدَهُمَا بِالْآخَرِ فَلَا يُفَارِقْكَ وَبَيْنَكَ وَبَيْنَهُ ‏ ‏لَبْسٌ ‏","","",""],[4987,4987,"","আমরা একটি ছেলের জন্য কথা বলেছি যে পাথরের বিধবা ছিল। তিনি প্রার্থনা করেছিলেন যে, তার দুই হাঁটু ছিল এবং তিনি বলেছিলেন যে, নবী তার কাছে এসেছিলেন এবং তিনি হয়ত তা করতেন পৌঁছে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْعُمَرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏رَمَلَ ‏ ‏مِنْ الْحَجَرِ إِلَى الْحَجَرِ ثَلَاثًا وَمَشَى أَرْبَعًا وَصَلَّى عِنْدَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ ثُمَّ ذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَهُ ‏","","",""],[4988,4988,"","আমরা কিছু বয়সের কথা বলেছি যারা আমাদের দুইজনকে খুন করার চেষ্টা করছে, আমি আল্লাহ তাকে চিনত আর তাকে পাথর মারার শিক্ষা দেয়া হবে আর ধার্মিক হতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا تَرَكْتُ اسْتِلَامَ الرُّكْنَيْنِ فِي شِدَّةٍ وَلَا رَخَاءٍ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا الْحَجَرَ وَالرُّكْنَ ‏ ‏الْيَمَانِيَ ‏","","",""],[4989,4989,"","আমরা একে অপরের সাথে কথা বলেছি, বাবার রাজধানীতে ফিরে আসতে পেরে খুশি, তুমি কি আমার নাম দিতে নাকি একটা সালাদের শব্দ শুনেছ?","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي عَاصِمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الصَّلَاةِ ‏ ‏بِمِنًي ‏ ‏قَالَ هَلْ سَمِعْتَ ‏ ‏بِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ نَعَمْ وَآمَنْتُ بِهِ قَالَ فَإِنَّهُ كَانَ ‏ ‏يُصَلِّي ‏ ‏بِمِنًي ‏ ‏رَكْعَتَيْنِ ‏","","",""],[4990,4990,"","আমরা বিচার এবং একটি অভিজাত পুত্র সন্তানের জন্য কিছু সমস্যা তৈরি করেছি. তারা একটি পায়ের জন্য প্রার্থনা এবং বলা হয় যে ভবিষ্যদ্বাণী তাকে যে ভাবে উপস্থাপন করেছে এবং আমরা এর জন্য আত্মসমর্পণ করেছি জায়গামত।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏وَسَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏صَلَّاهُمَا بِإِقَامَةٍ وَاحِدَةٍ فَقَالَ هَكَذَا صَنَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَا فِي هَذَا الْمَكَانِ ‏","","",""],[4991,4991,"","আমরা অনেকবার কথা বলেছি, কিন্তু আমরা আমার মন হারানোর স্বপ্ন দেখেছি... ...একজন ভালো কাপুরুষকে সাহায্য করার জন্য, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি তাদের ঋণ শোধ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدَّهِنُ بِالزَّيْتِ غَيْرِ ‏ ‏الْمُقَتَّتِ ‏ ‏عِنْدَ الْإِحْرَامِ ‏","","",""],[4992,4992,"","আমরা একে অপরের ছেলের কথা বলেছি, বাবা এক ছেলের জন্য চলে গেছে, যে এক বছরের ছেলে জন্ম নিয়েছে তার জন্য। সে বলল, ঈশ্বরের কাছে প্রার্থনা করতে হবে এবং তাকে উদ্ধার করতে হবে। আবার শাস্তি পেতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَعَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَلْبَسُ الْمُحْرِمُ ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏وَلَا ‏ ‏زَعْفَرَانٌ ‏","","",""],[4993,4993,"","আমরা দুই মাস ধরে ঈশ্বরের প্রভুর পুত্র... ...তার নিজের মত করে ভগবানের জন্ম দিয়েছেন.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَ الْمُحْرِمُ ثَوْبًا ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏أَوْ ‏ ‏زَعْفَرَانٌ ‏","","",""],[4994,4994,"","আমরা একে অপরের সাথে ঘোড়ার পিঠে কথা বলেছি, যে ঘোড়াটা মানুষ হতে হবে। আমি যা করছি বা ঘুমিয়েছি, তার জন্য আমি আমার ছেলেকে মেরে ফেলব, যে আল্লাহ্‌র পাপের জন্য ঈশ্বর করেছেন। টমেটোর","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ رَجُلٍ نَذَرَ أَنْ يَصُومَ يَوْمًا فَوَافَقَ يَوْمَئِذٍ عِيدَ أَضْحَى ‏ ‏أَوْ يَوْمَ فِطْرٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَمَرَ اللَّهُ بِوَفَاءِ النَّذْرِ وَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ هَذَا الْيَوْمِ ‏","","",""],[4995,4995,"","আমরা দুই বছর ধরে কিছু কাজ করেছি, একটা কুত্তার বাচ্চা খুঁজতে চেষ্টা করেছি, সে বলল সে ঈশ্বরের কাছে প্রার্থনা করতে হবে যাতে সে যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يَقْرُنَ ‏ ‏الرَّجُلُ بَيْنَ التَّمْرَتَيْنِ حَتَّى يَسْتَأْذِنَ أَصْحَابَهُ ‏","","",""],[4996,4996,"","আমরা বেঁচে থাকার জন্য কথা বলেছি, ঈশ্বরের পুত্র হওয়ার স্বপ্নের জন্য তারা একটা মুরগী তৈরি করছে, তারা বলছে ঈশ্বর তার জন্য প্রার্থনা করছে এবং তাকে উপস্থাপন করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ وَهُوَ ابْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ مَرَّ عَلَى قَوْمٍ نَصَبُوا دَجَاجَةً يَرْمُونَهَا بِالنَّبْلِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُمَثَّلَ بِالْبَهِيمَةِ ‏","","",""],[4997,4997,"","আমরা একে অপরের শপথ করেছি, যে কিনা ঈশ্বরের কাছে তার শান্তি ও শান্তি রক্ষা করেছে। সে তার কল্পনার মধ্যে পরেছিল যে, ঈশ্বরের মৃত্যু হতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَرَّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[4998,4998,"","আমরা দুজন জীবনের জন্য একে অপরের সাথে কথা বলেছি আর তার ছেলে ছেলে হওয়ার ব্যাপারে আমাদের ভাল বলেছে, সে এটা করেছে, সে করে দিয়েছে, আর সে একটা আংটির ব্যবস্থা করেছে যাতে মানুষ তার মুখ থেকে বের হয়ে যায়। সে বলেছে সে মানুষকে ভয় দেখাতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ ذَهَبٍ فَاتَّخَذَ النَّاسُ خَوَاتِيمَهُمْ مِنْ ذَهَبٍ فَرَمَى بِهِ وَقَالَ لَنْ أَلْبَسَهُ أَبَدًا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَنَبَذَ ‏ ‏النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[4999,4999,"","আমরা আমার বাবার ছেলে, একজন দেবীর পুত্র, ঈশ্বরের পুত্র, একজন দেবীর ছেলে, তার মুখ বন্ধ করে দিচ্ছিলাম। নাক।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي رَوَّادٍ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَجْعَلُ فَصَّ خَاتَمِهِ مِمَّا يَلِي بَطْنَ كَفِّهِ ‏","","",""],[5000,5000,"","আমরা কিছু সময় কথা বলেছি অন্যায় কাপড় পরা ছেলে আর ছেলের ভালোর জন্য যে ভুল কাপড় পরে ছিল, আর সে বলেছে যে, নবী প্রার্থনা করেছেন সে এটা রেখে দিত.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏وَنَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَلْبَسُ ‏ ‏السِّبْتِيَّةَ ‏ ‏وَيَتَوَضَّأُ فِيهَا وَذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""]];
